window.PARAGRAPH8_EXPANDED_QUESTIONS = [{"id":"g8-lsg-lsg1-03-14","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"(I) Neşe de bahar gibi yeni bir doğuşu ve taze bir oluşu müjdeler. (II) İhtiyar tabiat, baharla gençleşir; ölümlü hayat, neşe ile yeniden canlanır. (III) Neşe, huzur ve sükûnunun da vaktidir. (IV) Neşeli bir yüz; güneşli bir hava gibidir, herkesin içini ısıtır.","stem":"Bu parçada numaralanmış cümlelerle ilgili aşağıdakilerden hangisi söylenemez?","options":["I. cümlede karşılaştırma yapılmıştır.","II. cümlede kişileştirmeye başvurulmuştur.","III. cümlede örnekleme vardır.","IV. cümlede benzetme söz konusudur."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg1-04-12","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Pisagor, Dünya’nın yuvarlak olduğuna dair araştırmalar yapmış ancak görüşlerine o zamanlar fazla değer verilmemiştir; Macellan, Dünya’nın yuvarlak olduğunu deniz yolculuğuna başladığı yere tekrar geri dönmesiyle ispatlamıştır.","stem":"Bu parçadan aşağıdakilerden hangisi kesin olarak çıkarılır?","options":["Macellan, Pisagor'dan önce doğmuştur.","Macellan, Dünya'nın şeklinin yuvarlak olduğunu fiilen ispatlamıştır.","Macellan'dan önce Dünya'nın şeklinin yuvarlak olduğunu düşünen yoktur.","Pisagor deniz yolculuğuna çıkmamıştır."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg1-05-10","grade":8,"topic":"Anlatım biçimleri","difficulty":"Zor","outcome":"Anlatım biçimleri","text":"Konağı hesaba katmazsak, amcamın evi mahallenin en yüksek eviydi. Kocaman bir taraça vardı üst katta. Çok güzel bir görünümü vardı taraçanın. Amcam, övünürdü evinin görünümüyle. “Her yer ayak altında.” derdi...","stem":"Bu metinde aşağıdaki düşünceyi geliştirme yollarından hangisi vardır?","options":["Tanımlama","Benzetme","Örneklendirme","Karşılaştırma"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg1-05-16","grade":8,"topic":"Yardımcı düşünce","difficulty":"Zor","outcome":"Yardımcı düşünce","text":"Hayatta başarılı olmak düşüncelerimizi, duygularımızı başkalarına etkili biçimde anlatmamıza bağlıdır. Anlatımda başarı ise okumakla gerçekleşir. Böylesine önemli olan okuma işi rastgele yapılmaz. Onun kurallarını iyi bilmek gereklidir. Bu amaçla okuma kurallarını iyi bilmeli, bol bol okumalıyız.","stem":"Bu metinden aşağıdaki yargılardan hangisi çıkarılamaz?","options":["Başarılı olabilmek için düşünce ve duygularımızı etkili biçimde anlatabilmeliyiz.","Başarılı olmak için dayanışma içinde olunmalıdır.","Okumak anlatımımızın başarılı olmasını sağlar.","Okumanın da kuralları vardır ve bunları iyi bilip bol bol okumalıyız."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg1-05-27","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"KORONA VİRÜS: SARS ve MERS virüsü ailesinden olduğu açıklanan Korona virüsü ilk defa 29 Aralık 2019'da Çin'in Wuhan şehrinde görüldü. Bulaşma Yolları: “İnsandan insana solunum yolu, öksürük, hapşırık, dokunma, el sıkma, sarılma, mutfak gereçlerinden ortak yeme içme ve hasta kişiyle yakın mesafeden konuşma, bulaşmaya neden olabiliyor. Belirtileri: “Hastalarda 39 dereceyi bulan yüksek ateş, öksürük ve nefes darlığı ile seyrettiği, boğaz ağrısı, burun akıntısı da gözlenen şikâyetler arasında yer alıyor. Korunma yolları: ☻“Eller su ve sabunla en az 20 saniye yıkanmalı veya el dezenfektanı kullanmalı, ☻Yüze, ağza, buruna yıkanmamış ellerle asla dokunmamalı, ☻Hasta insanlarla yakın temasta bulunmamalı, ☻Kapı kolu, telefon, klavye gibi ortak kullanılan ve sıkça dokunulan nesneleri sıkça temizlemeli ve dezenfekte etmeli, ☻Öksürük ve hapşırık sırasında ağız mendil ile kapanmalı. KUŞ GRİBİ: İnfluenza virüslerinin neden olduğu ve kuşlardan geçen bir hastalık olarak bilinen kuş gribi, 100 yıldan daha uzun zaman önce ilk olarak İtalya'da ortaya çıkan ve daha sonra dünyanın farklı yerlerinde de zaman zaman görülen bir hastalıktır. Bulaşma Yolları: Hastalığın bulaşma şekli sadece hasta hayvanlar ile yakın temas sonucu olur.. Belirtileri: Boğaz, kas, baş, karın, akciğer ağrısı, kusma, ishal, öksürük ve ateş ilk belirtilerdir. Hastalık bulaştıktan 2-3 saat ya da 3-4 gün içerisinde kendini gösterir. Hücrelere yeterli miktarda oksijen gitmediği için vücutta morarma ortaya çıkar. Korunma yolları: Hastalığın görüldüğü ülkelere ya da bölgelere seyahat edenler, hastalığın bulunduğu tavuk çiftliklerinden uzak durmalı, iyi piştiğinden emin oldukları kanatlı hayvan etlerinden yemeliler. Yumurtalar sabunlu su ile yıkanıp ısıları en az 70 derece olacak şekilde pişirilmeli, yumurta veya kanatlı hayvan etlerine dokunduktan sonra eller sabunlu su ile ile sık sık yıkanmalı, bu işler ile uğraşanlara gerekir ise koruyucu ilaç tedavisi ya da mevcut olan grip aşısı yapılmalıdır. ● 27. ve 28. sorular yukarıdaki metne göre cevaplandırılacaktır. 27.","stem":"Bu metinden hareketle aşağıdakilerden hangisi söylenemez?","options":["Kuş gribi ile ilgili ilaç ve aşı tedavisi vardır.","Korona virüs ile kuş gribi hastalığının ilk çıkış yerleri farklıdır.","Her iki hastalığa sebep olan virüs ailesi aynıdır.","Bulaşıcı bu iki hastalığın ortak belirtileri yüksek ateş, öksürük ve boğaz ağrısıdır."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg1-05-36","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Tarih; yönteminin yanı sıra incelediği konuların niteliği ve niceliği bakımından da diğer bilimlerden ayrılır. Örneğin matematik bilimi zamanı ve mekânı olmayan sayısal kavramları konu edinir. Tarih ise yeri ve zamanı belli olan, yaşanmış olaylarla ilgilenir. Tarihin farklılıklarından biri de başka bilim dallarına göre inceleme alanının daha geniş olmasıdır. Örneğin fizik, kimya, biyoloji gibi fen bilimleri birbiriyle bağlantılı ve tekrarlanabilir olayları inceler. Buna karşılık tarih aralarında sistematik ilişki bulunmayan, her biri kendine özgü, biricik olaylarla ilgilenir. Tarihçi, metinleri iyi anlamaktan başka ihtirasa sahip olmamalıdır ve bu gaye için yardımcı ilimlerin bütün tekniklerini kullanmak zorundadır, diyerek Fustel de Coulanges (Fustel dö Kulanj) tarihçinin görevini tanımlamıştır.","stem":"Bu parçanın anlatımında aşağıdakilerin hangisinden yararlanılmamıştır?","options":["Tanımlama","Örnekleme","Karşılaştırma","Tanık gösterme"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg1-05-45","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"(I) Brezilyalı bir bilim insanı, bir kokuyu yalnızca iki dakikada analiz edebilen bir sistem geliştirdi. (II) Bu, gerçek koku ile sahte kokunun buharlarının kimyasal imzalarını karşılaştıran taşınabilir bir makinedir. (III) İmza terimi, gerçek parfümü oluşturan farklı kimyasalların her şişede aynı olması gereken oranını anlatır. (IV) Sahte örneklerin imzaları farklıdır çünkü sahteciler aslıyla bire bir eşleşmeyi nadiren sağlayabilir.","stem":"Bu parçada numaralanmış cümlelerle ilgili aşağıdakilerden hangisi söylenemez?","options":["I. cümlede sistemin kim tarafından gerçekleştirildiğinden söz edilmiştir.","II. cümlede sistemde kullanılan makinenin özelliğinden bahsedilmiştir.","III. cümlede imza teriminin, adını nereden aldığı belirtilmiştir.","IV. cümlede sahte örneklerdeki imzaların neden farklı olduğu açıklanmıştır."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg1-05-22","grade":8,"topic":"Yardımcı düşünce","difficulty":"Zor","outcome":"Yardımcı düşünce","text":"6-10 Ocak 1920 tarihinde İngilizlerin desteklediği 20. Tanzimat Fermanı’nda tanınan can, mal, ırz güven- Yunanlılar, Batı Cephesine doğru harekete geçtiler. liği teminat altına alınmış olmakla birlikte asıl amaç Fakat düzenli ordu İnönü mevzilerini terk etmeyerek Müslümanlarla gayrimüslimlerin eşit haklara sahip Yunan Ordusunu durdurmayı başardı. Batı olmalarını sağlamaktı. Ayrıca gayrimüslimlerden cephesi komutanı İsmet İnönü Yunan kuvvetlerinin alınan cizye vergisinin kaldırılması kararlaştırılarak, durdurulduğunu meclise çektiği telgrafla şöyle devlet memuru olabilmelerinin de önü açılmıştı. bildirmiştir; Din ve mezhebinden ötürü gayrimüslimlere hakaret edilmesi kanunla yasaklanmış, bu insanların “Askerlerimiz bugün de aralıksız devam eden düşman mahkemelerdeki tanıklıkları da Müslüman bireylerin taarruzlarını, bir an gerilemeksizin göğüslüyorlar; tanıklıklarıyla eşdeğer sayılmıştır. Yunanlıların ilerlemesine imkan bırakmıyorlardı. Şüphesiz ki ordumuz bu taarruzlar karşısında ağır kayıplar veriyor; ama canından aziz bildiği kutsal vatan","stem":"Buna göre bu ferman ile alınan kararlara topraklarını her ne pahasına olursa olsun savunmaktan bakıldığında aşağıdakilerden hangisine geri kalmıyordu. En nihayet tükenen, gücü kırılan ulaşamayız? düşman oldu. İki gündür devam eden taarruzlarından bir başarı elde edemediğini ve edemeyeceğini anladı. Gayrimüslim halkın, toplumsal hayatta daha Artık bu safhada onlar için yapılacak bir şey vardı: Geri huzurlu yaşamaları amaçlanmıştır. çekilmek.” Hukuk alanında gayrimüslim halka yeni haklar Birinci İnönü savaşı ile ilgili verilen metinden yola tanınmıştır. çıkarak aşağıdakilerden hangisine ulaşılamaz?","options":["Türk Ordusu vatanını canı pahasına korumaktadır.","Savaşı Türk Ordusu kazanmıştır. Bu savaş Türk Ordusu’nun Batı Cephesi’ndeki ilk savaşıdır. Yunan Ordusu saldıran, Türk Ordusu savunan taraftır.","Gayrimüslimlerin orduda görev almasının yolu açılmıştır.","Mesleki anlamda gayrimüslimler için yeni düzenlemeler getirilmiştir."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg2-03-04","grade":8,"topic":"Anlatım biçimleri","difficulty":"Zor","outcome":"Anlatım biçimleri","text":"İlim olmadan gelişim olamaz. İlim öğrenmeye çalış ve bilgililerin bilgilisi ol. Bunun için “Beşikten mezara kadar ilim öğreniniz!” sözünü ilke edin.","stem":"Bu paragrafta aşağıdaki düşünceyi geliştirme yollarından hangisine başvurulmuştur?","options":["Tanık gösterme","Örnekleme","Tanımlama","Sayısal verilerden yararlanma"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg2-03-06","grade":8,"topic":"Yardımcı düşünce","difficulty":"Zor","outcome":"Yardımcı düşünce","text":"Mısır “Nil’in Hediyesi” olarak bilinir. Bunun nedeni Sahra Çölü’nün doğu ucunda yer alan Mısır’ın, Nil Nehri olmasaydı tamamen yaşanamayan bir bölge olacak olmasından kaynaklıdır. Bu nehir sadece Mısır’a değil aynı zamanda kültür ve medeniyetin görkemli tarihine de hayat vermiştir. Nehir yaklaşık 6650 km uzunluğundadır. Birden fazla iklim bölgesinden geçerek Akdeniz’e dökülür. Güneyden kuzeye doğru akar ve üç ana kolu vardır: Beyaz Nil Nehri, Mavi Nil Nehri, Atbarah Nehri. Havzasında 11 ülke yer alır: Tanzanya, Burundi, Ruanda, Kongo, Kenya, Uganda, Etiyopya, Güney Sudan, Eritre, Sudan ve Mısır. Bu arada nehrin kenarında büyüdüğü bilinen papirüs bitkisi, Mısırlılar tarafından dünyadaki ilk kâğıdı hazırlamak için kullanıldı. Kısacası Nil nehri piramitlerin yapımında, taşımacılıkta kullanılmasından başka turizm, hayvan türlerinin doğal yaşam alanı, medeniyet gibi birçok konuda Mısır ve çevresine hayat vermiştir.","stem":"Bu metinde Nil Nehri ile ilgili aşağıdakilerden hangisine değinilmemiştir?","options":["Beslendiği kaynaklara","Uzunluğuna","Geçtiği ülkelere","Bölge üzerindeki etkisine"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg2-03-08","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"(I) Gabriel Garcia Marquez 1982’de Nobel Edebiyat Ödülü’nü almıştır. (II) “Yüzyıllık Yalnızlık, Kırmızı Pazartesi, Mavi Köpeğin Gözleri” eserlerinden bazılarıdır. (III) Yazar “Yüzyıllık Yalnızlık”ta kendi çocukluğunu, ailesini işlemiştir. (IV) Yalnız bu kitabı okumak öyle kolay değil.","stem":"Numaralanmış cümlelerden hangisi kanıtlanabilirlik açısından farklıdır?","options":["I.","II.","III.","IV."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg2-05-04","grade":8,"topic":"Yardımcı düşünce","difficulty":"Zor","outcome":"Yardımcı düşünce","text":"Bütün canlıların vücutlarının,uyuma,vücut ısısı,üreme zamanı gibi periyodik fonksiyonlarını kontrol eden biyolojik bir iç saatleri vardır. Bu iç saatlerin çoğu, kendi fonksiyonları için kendi zaman dilimlerinde çalışır, ancak ışık ve sıcaklık gibi dış etkenlerden de etkilenir. ABD’ye uçarsanız sizin vücut saatiniz hala Türkiye’ye ayarlıdır. İstanbul’dan saat 12.00’de havalanır, 8 saatlik bir uçuştan sonra New York’a varırsanız vücut saatiniz 20.00’dedir. Ama New York saat 13.00’ü yaşamaktadır. Vücudunuzun saati ortama göre 7 saat ileridedir. Karnınız acıkacak, biraz sonra uykunuz gelecektir ama akşam olmasına bile daha 7, 8 saat vardır. İşte bu olaya geri kalma, gecikme anlamında jet-lag denir. Bu durumda insanda yorgunluk duyulmakta, özellikle okuma, araba kullanma ve iş görüşmeleri gibi konularda motivasyon ve konsantrasyon eksikliği görülmektedir. Dünya dönüşünü 24 saatte tamamladığından, Dünya yüzeyi kuzeyden güneye her biri 1 saatlik 24 zaman bölgesine bölünmüştür. İstanbul ile New York arasında 7 zaman bölgesi vardır. Aynı anda İstanbul’da saat 14.00 iken New York’ta sabah saat 07.00’dir. NASA’ya göre insan vücudunun biyolojik saatinin her bir zaman bölgesine, yani 1 saatlik zaman değişimine alışması bir gün almaktadır.","stem":"Bu durumda İstanbul’dan New York’a gidince vücut kendini ancak 7 gün sonra adapte edebilmektedir. Jet-lag olayı uçma mesafesine değil, kaç zaman bölgesinden geçtiğinize bağlıdır. Aynı mesafe, aynı zaman bölgesinde kuzey-güney mesafesinde gidilince jet-lag olayı görülmemektedir. Yapılan anketler sonucunda, insanların doğuya doğru yapılan uçuşlarda daha çok rahatsız olduğu, insanın vücut saatini hızlandırmada, yavaşlatmaya göre daha fazla zorlandığı görülmektedir. Bu metinden aşağıdakilerden hangisi çıkarılamaz?","options":["Jet-lag olayı zaman dilimi değişikliklerinde doğu-batı ve batı-doğu istikametinde oluşmaktadır.","Jet-lag olayı bazı olumsuz durumlara ve motivasyon kaybına sebep olmaktadır.","Doğuya gidildikçe vücut saati hızlanmalı, batıya gidildikçe yavaşlamalıdır.","Vücut saatiniz gittiğiniz yerden dönene kadar bulunduğunuz yere alışmamaktadır."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg3-02-04","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Göbeklitepe, Şanlıurfa il merkezinin yaklaşık 22 km kuzeydoğusunda, Örencik köyü yakınlarında yer alan dünyanın keşfedilmiş en eski dinî yapılar topluluğudur.","stem":"Aşağıdakilerden hangisi bu cümleden kesin olarak çıkarılacak bir yargıdır?","options":["Göbeklitepe, Şanlıurfa’nın en eski yerleşim yeridir.","Dünyanın keşfedilmiş en eski dinî yapılar topluluğu Göbeklitepe’dir.","Göbeklitepe, Şanlıurfa’nın yaklaşık 22 km kuzeybatısında yer alır.","Örencik köyündeki insanlar dinî yapılarda yaşamaktadır."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg3-02-05","grade":8,"topic":"Metinde yapı","difficulty":"Zor","outcome":"Metinde yapı","text":"(I) Farklı kaynaklardan elde edilen enerjinin depolanmasını ve uygun maliyetli teknolojilerin geliştirilmesini amaçlayan çalışmalar hızla devam ederken bir yandan da alternatif enerji kaynakları geliştiriliyor. (II) Bugün ağaçlardan, bitkilerden, nehirlerden hatta çöplerden bile enerji elde ediliyor. (III) Çalışmalarına Columbia Üniversitesinde devam eden Doç. Dr. Özgür Şahin, havadaki nem değişimlerinin kaynağı olan buharlaşmadan elektrik elde edebilen bir jeneratör geliştirdi. (IV) Dr. Şahin; moleküllerde ve canlı hücrelerde rastlanan sıra dışı mekanik olayları gözlemleyip açıklamak ve bunlardan ilham alarak sağlık, çevre ve enerji ile ilgili önemli sorunlara çözüm olabilecek yeni teknolojiler geliştirmek üzerine çalışmalar yapıyor.","stem":"Bu parçada numaralanmış cümlelerin hangisinden sonra düşüncenin akışına göre “Bu kaynaklara bir yenisi de yakın zaman önce Doç. Dr. Özgür Şahin tarafından eklendi.’’ cümlesi getirilmelidir?","options":["I.","II.","III.","IV."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg3-03-01","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Türkçe Soruları 1. Güneş kendini yeni yeni göstermeye başlamışken dışarıdan gelen kuş sesleri ve mutfaktan gelen mis gibi kokular eşliğinde gözlerini açtı Ayşe. Köyde sabahlar daha mı güzel oluyor ne, diye düşündü. Sanki hızlı hareket ederse kuş sesleri gidecekmiş gibi usulca kalktı yatağından, kuşları görmek için bahçeye çıktı. Oysa bahçede daha ne sürprizler vardı onun için: Mis gibi kokan hanımeliler, rengârenk ortancalar, kiraz ağacının üstündeki serçeler, âdeta bir tablo gibi etrafı süsleyen papatyalar… İyi ki gelmişim buraya, dedi kendi kendine.","stem":"Bu metinde ağır basan anlatım tekniği aşağıdakilerden hangisidir?","options":["Açıklama","Betimleme","Tartışma","Öyküleme"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg4-01-11","grade":8,"topic":"Yardımcı düşünce","difficulty":"Zor","outcome":"Yardımcı düşünce","text":"Orta Asya’nın en büyük çöllerinden olan Kızılkum’un ortasında Zerefşan Ovası’nın aşağı kesiminde yer alan, tarihte Doğu ile Batı’yı İpek Yolu üzerinden bağlayan, kültürlerin, dinlerin ve ticaretin kesişme noktası olan Buhara kenti, Türk-İslam medeniyetinde önemli bir yere sahiptir. Türk devletlerinin siyasi ve kültür merkezlerinden olan Buhara, yetiştirdiği bilim ve din adamlarıyla dünyada “Kubbet-ül İslam” unvanına sahip 3 şehirden biri sayılıyor. Bugün devlet korumasına alınmış 700’e yakın tarihi ve kültürel miras niteliğinde yapıtın bulunduğu Buhara, 1993’te BM Eğitim, Bilim ve Kültür Örgütü (UNESCO) tarafından Dünya Mirası Listesi’ne alındı. Buhara’da yüzyıllar önce inşa edilen Han Sarayı, Hazreti Eyüp Çeşmesi, İsmail Samani Türbesi, Uluğ Bey Medresesi, Minare-i Kelan (Büyük Minare), Pay-i Kelan ve Mir Arap Medresesi gibi tarihi yapıtlar, turistlerin en uğrak yerleri olmayı sürdürüyor.","stem":"Verilen parçada Buhara ile ilgili aşağıdaki bilgilerden hangisine ulaşılamaz?","options":["Dünyada konum olarak nerede bulunduğuna","UNESCO tarafından Dünya Mirası Listesi’ne alındığı yıla","“Kubbet-ül İslam” unvanına sahip olma nedenine","Burada yaşamış önemli bilim insanlarının isimlerine"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg4-01-13","grade":8,"topic":"Konu ve başlık","difficulty":"Zor","outcome":"Konu ve başlık","text":"Aşağıda, bir bilim kurgu kitabının içindekiler kısmından bazı bölüm başlıkları verilmiştir. İÇİNDEKİLER BÖLÜMLER Uzaylılar Geliyor......................................................................... 11 Ay'a Yolculuk ve Buluşma............................................................ 22 Uzaylıların Tarihi........................................................................ 31","stem":"Buna göre aşağıda kitabın bölümlerinden alınan parçalar ile verilen başlıklar eşleştirildiğinde hangisi dışta kalır?","options":["Sıradan bir nisan günüydü. Yeryüzünün kuzey yarım küresi yaza, güney yarım küresi ise kışa hazırlanıyordu. Kuzey yarım kürede doğa, birbirinden renkli sayısız çiçekle bezenmişti. Güney yarım kürede ise kara kışın habercisi kara bulutlar gökyüzünü kaplamaya başlamıştı. Hepimizin yakından bildiği çevre kirliliği, atmosferin aşırı ısınması, çeşitli bölgelerde çekilen açlık, su sıkıntısı gibi sorunlarla boğuşulurken televizyon kanallarından yayınlanan bir haber tüm dünyayı yerinden oynattı. Dünyaya doğru ilerlemekte olan çok sayıda uzay cisimleri belirlenmişti.","Barışçıl bir ilişki kurulmuştu artık uzaylılarla. İyi de bundan sonra ne olacaktı? “Onlara bir temsilci yollamalıyız.” dedi Bilgin Amca. Birleşmiş Milletler Genel Kurulu oy birliğiyle bu temsilcinin Bilgin Amca olmasına karar verdiyse de o karşı çıktı buna. Kısa bir oylamadan sonra Berk Yüzbaşı ile Doğay’ın bir uzay mekiğiyle Ay’a, Ay’ın karanlık tarafına üs kurmuş olan uzaylılara elçi olarak gönderilmesine karar verildi.","Toplantıya ara verildiğinde Doğay ve Akita bilgisayarlarını kapatıp bu ciddi soruna çözüm getirebilecek konuları tartışmaya başladılar. Bir çözüme ulaşamadıklarını gürünce tartışmayı bıraktılar. “Gel sana kenti gezdireyim.” dedi Akita. Burası her yanı ağaçlar, çiçekler, parklarla süslü büyük bir kentti. Kent içi ulaşım yer altındaki hızlı trenlerle ya da yerçekimini yok eden özel bir sistemle donatılmış küçük hava araçlarıyla gerçekleştiriliyordu.","Tıpkı günümüzde insanların yaptığı gibi uzaylılar da binlerce yıldır evrenin dört bucağını gözlemleyip ilişki kurabilecekleri başka bir zeki canlıların olup olmadığını araştırmaktaydılar. Sonunda 3 bin yıl kadar önce Güneş Sistemi’ni ve Dünya’yı bulmuşlardı. Bu buluş büyük bir sevinç kaynağı olmuştu onlar için. Ama dünya üzerindeki uygarlıklar henüz ilkeldi. Zaman içinde dünya uygarlıkları hızla gelişiyordu ama bir yandan da büyük savaşlar yaşanıyordu. Oysa uzaylıların kendi gezegenlerinde savaşlar çok uzun zaman öncesinde kalmıştı. Ordular kaldırılmış, silahlar yok edilmişti."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg4-02-07","grade":8,"topic":"Yardımcı düşünce","difficulty":"Zor","outcome":"Yardımcı düşünce","text":"20.yüzyılda yaşamış aşı biliminde uzmanlaşmış bir mikrobiyolog. Hilleman, ABD’nin en yüksek bilimsel onuru ve Dünya Sağlık Örgütün- 30 Ağustos 1919 tarihinde Ameden ömür boyu başarı ödülü de dâhil rika’nın Montana eyaletinde bir birçok ödüle layık görüldü. çiftlikte doğdu. Kabakulak, kızamık, hepatit A ve B, suçiçeği, menenjit, zatürre gibi Ailenin sekizinci çocuğuydu. ölümcül olan 40’tan fazla hastalığın aşısını buldu. 1957 grip salgınının büyük bir salgın olabileceğini fark etti. Hil- Maddi durumlarının kötü olması leman aylar sonra aşıyı bulana nedeniyle üniversiteye gideme- (1919 - 2005) kadar dünya çapında bir milyonyecekti. Büyük abisinin desteğiydan fazla insan hayatını kaybetle üniversiteye başladı. mişti. Bu salgın durdurulmasaydı 1944’te mikrobiyoloji doktora derecesini dünya çapında milyonlarca insan aldı. Klamidyaya neden olan bakteriler ve hayatını kaybedecekti. bu hastalığın iyileşme imkânı ile ilgili keşif yaptı.","stem":"Bu parçadan “Maurice Hilleman”la ilgili aşağıdakilerden hangisi çıkarılamaz?","options":["Alanında uzmanlaşarak pek çok buluş yapmıştır.","Başarılarından dolayı birçok ödül almıştır.","Büyük bir salgının aşısını bularak can kaybını önlemiştir.","İlk çalışmasını virüsler üzerine yapmıştır."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg4-02-13","grade":8,"topic":"Yardımcı düşünce","difficulty":"Zor","outcome":"Yardımcı düşünce","text":"Tarihler 15 Ocak 2009’u gösterirken New York Hudson Nehri’nde büyük bir mucize yaşandı. US Airways’e ait Airbus A320 tipi uçak, LaGuardia Havalimanı’ndan kalkışından hemen sonra kuş sürüsüne girdi. Her biri 15-20 kilogram I ağırlığındaki Kanada kazları, A320’nin iki motorunun da durmasına neden oldu. II İçinde 155 yolcu ve mürettebat bulunan 78 ton ağırlığındaki uçak, adeta motorsuz hava taşıtı ‘planör’ hâline gelmiş- III ti. 1549 sefer sayılı A320’nin tek kurtuluşu Hudson Nehri’ne yapacağı inişti. Kaptan Chesley Burnet ‘Sully’ Sullenberger, zor bir karar verdi. Hudson Nehri’ne mükemmel planlamayla başarılı bir iniş yaptı. Tıpkı gençliğinde küçücük bir planörle yaptığı inişlerdeki gibi kusursuzdu. Yolcuların ve ekibinin hayatını kurtardı. Sullenberger, ulusal IV kahraman hâline geldi.","stem":"Bu metinden aşağıdakilerden hangisi çıkarılamaz?","options":["Uçak kalkıştan hemen sonra kuş sürüsüne çarpmıştır.","Sürüye çarpmak bir motorun arızalanmasına sebep olmuştur.","Kaptan uçağın nehre iniş yapmasını sağlamıştır.","Yolcular ve ekipten can kaybı olmadan kaza atlatılmıştır."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg4-03-05","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Eğer sizden sokakları süpürmeniz istenirse Michelangelo’nun veya Shakespeare’in yazdığı gibi süpürün. O kadar güzel süpürün ki gökteki ve yerdeki herkes durup “Dünyanın en iyi çöpçüsü galiba burada çalışıyor.” desin.","stem":"Bu parçada anlatılmak istenen düşünce aşağıdakilerden hangisidir?","options":["Bir şeyleri iyi yapmak insanda tarifsiz mutluluklara yol açar.","En iyisini yapma çabası kişiyi bazen başarısız kılabilir.","Kimi dâhiler, ortaya koydukları işlerle zamanı aşmışlardır.","İnsan her işinde, elinden gelenin en iyisini yapmaya çalışmalıdır."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg4-03-06","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Çanakkale Savaşı’nı konu edinen bu romanda, kahramanların çoğunun tarihî şahsiyetlerden oluştuğu ve olayların anlatımında yine tarihî gerçekliğe bağlı kalındığı görülmektedir. I.Dünya Savaşı’nın nasıl başladığı, Osmanlı Devleti’nin bu savaşa nasıl girdiği, o yıllarda diğer cephelerde neler yaşandığı gibi pek çok konu üzerinde durulan eserde; hikâye metni dışında bir ön söz ve bir de kaynakça yer almaktadır. Bu metnin anlatımıyla ilgili","stem":"Aşağıdakilerden hangisi söylenebilir?","options":["Bir konu ile ilgili açıklama, bilgilendirme yapılmıştır.","Bir yerin özellikleri göz önünde canlanacak şekilde tanıtılmıştır.","Bir yaşam kesiti, belli bir olaya bağlı olarak anlatılmıştır.","Bir husus hakkında kişisel görüş dile getirilmiştir."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg4-04-10","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"“Sadaka taşı” Osmanlı Devleti’nin egemenliği altında bulunan yerleşim yerlerinde, insanlar arasındaki dayanışmanın en güzel örneklerindendi. Özellikle gece saatlerinde, hayırsever insanlar ile ihtiyaç sahibi insanların uğrak yeriydi. Yardım yapmak isteyen kişi, kibirlenmekten korktuğu için gizlice sadakasını taşın içine bırakırdı. İhtiyaç sahibi de eziklik hissetmeden ihtiyacı kadar olanı oradan alır, kullanırdı. Sessiz yardımlaşma ve samimiyetin en zarif uygulamalarından biri olan sadaka taşından yardım alanlar, daha sonra durumu düzelince aldıkları parayı muhtaç durumdaki başka insanlar ihtiyacını gidersin diye sadaka taşına geri bırakırdı. Bu uygulama hırsızlık, yoksulluk gibi olumsuzlukların da önüne geçerdi.","stem":"Bu metinde sadaka taşı uygulaması ile ilgili aşağıdakilerden hangisi yoktur?","options":["İsminin nereden geldiği","Nasıl uygulandığı","Hangi faydaları sağladığı","Amacının ne olduğu"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg4-04-11","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Tahran’da başıma gelenlerin hepsini yazmaya kalksaydım muhtemelen on cilt kitap çıkardı ortaya ve siz onu okurken yorgun düşerdiniz. Bu yüzden sadece son yirmi dört saatte neler yaşadığımı anlatacağım. Elbette önce sizlere babamla birlikte Tahran’a niçin geldiğimizi anlatmam gerekiyor. Çalışmak için… Daha önce buraya gelip iş güç edinen akrabalarımız davet etmişti bizi. Bir tanıdığımızın dondurma tezgâhı vardı. Bir diğeri bebek giysileri ve ikinci el kıyafetler alıp satıyordu. Bir başkasıysa portakal satıcısı olmuştu. Babam da ne yapıp edip tahta bir manav arabası bulmuş ve seyyar satıcılığa başlamıştı.","stem":"Bu metinde aşağıdakilerden hangisi yoktur?","options":["Neden-sonuç ilgisi kurma","Özlem duyma","Örnek verme","Tahminde bulunma"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg5-01-10","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Malezya’nın başkenti Kuala Lumpur’daki Malezya Uluslararası Ticaret ve Sergi Merkezi’nde düzenlenen 2020 Küresel İnsansız Hava Araçları Konferansı’na İHA ile ilgili çok sayıda savunma sanayi şirketi temsilcileri katıldı. Konferansta bu yıl, dünyada İHA teknolojisinin geldiği son nokta, İHA yapımında yapay zekâ kullanımı ve İHA’nın afetlerle mücadelede kullanımı müzakere edildi. İki gün süren konferansa Türkiye’den katılan İstanbul Teknik Üniversitesi Havacılık ve Uzay Mühendisliği Birimi Öğretim Üyesi Dr. İsmail Bayezit, havacılık teknolojisindeki gelişmelerin gelecekte şehirlerdeki hava trafiğini nasıl etkileyeceğine dair bir panelde konuştu. Bayezit, Türkiye’nin teknoloji üretiminin gelişmesine dair yaptığı çalışmalara da değinerek Türkiye Akademik ve Bilimsel İş Birliği Projesi (TABİP) kapsamında yapılan çalışmaların önemine dikkat çekti. Türkiye’de 2018’den bu yana düzenlenen TEKNOFEST’te kurulan atölyelerin ortaokul ve lise öğrencilerini teknolojik çalışmalara yönlendirdiğini katılımcılara anlatan İsmail Bayezit, “Türkiye bu tür çalışmalar sayesinde ilerleyen yıllarda hem İHA üretiminde hem başka alanlarda teknoloji üretiminde uluslararası pazarda yerini artıracaktır.” dedi.","stem":"Bu haber metninden, I. Malezya İHA üretiminde başarılı ülkelerden biridir. II. İHA’lar gelecekte birden çok sorunun çözümüne katkı sunacaktır. III. Bu tür konferanslara ilgi her geçen gün artmaktadır. IV. İHA’lar teknoloji üretimine katkı sunan kuruluşlarca geliştirilmiştir. V. Teknoloji geliştirmede gençlerin katılımı önemlidir. yargılarından hangilerine ulaşılabilir?","options":["I., II. ve VI.","II., IV. ve V.","III., IV. ve V.","I., II., IV. ve V."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg5-01-12","grade":8,"topic":"Yardımcı düşünce","difficulty":"Zor","outcome":"Yardımcı düşünce","text":"İnsanlık tarihi; toplumların, devletlerin ve milletlerin; savaşlarla, afetlerle, salgın hastalıklarla sınandığı olaylarla ve olgularla doludur. Bu sınavların hemen hepsinde sınananların yanında onları uzaktan seyreden, onlara acıyan, yardım eden ya da gülüp geçen başkaları da olmuştur. Çünkü savaş, afet, salgın onlara ulaşmamış, sadece içinde doğduğu coğrafyadakileri etkilemiştir. Bugün yaşanan salgın -Kovid 19- belki de ilk defa tüm insanlığın sınavına dönüşmüştür. Kendini dev aynasında gören ve doğanın hâkimi olduğuna inanan insanoğlunun canlı olduğu bile tartışılan bir virüs tarafından dize getirilmesine dayalı bir imtihan. Birkaç ay içinde tüm dünyayı saran bu yangının modern insanın en çok övündüğü hız ve küreselleşme gibi modern kavramlardan güç aldığı unutulmamalıdır. Bundan sonra dünyaya, izleyeceği yol konusunda bu tecrübelerin neler söylediğini anlayan var mıdır? Göreceğiz…","stem":"Bu metinden aşağıdaki yargılardan hangisi çıkarılamaz?","options":["Bir musibet, bin nasihatten hayırlıdır.","İnsanoğlu bazı zamanlarda felaketlere kayıtsız kalmıştır.","Modernleşme insanlığın aleyhine işlemektedir.","Virüsün yayılımında hız ve küreselleşme etkili olmuştur."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg5-01-14","grade":8,"topic":"Yardımcı düşünce","difficulty":"Zor","outcome":"Yardımcı düşünce","text":"Yeryüzünün en sevimli hayvanlarından biri olan pandalar, yaklaşık 100 g ağırlığında doğarlar, büyüdüklerinde bu rakam 90 ile 135 kg arasında değişir. Siyah beyaz renktedirler, yaşamlarını bambu ormanlarının yoğun olduğu sisli dağ eteklerinde geçirirler. Utangaçtırlar, yalnız kalmayı çok severler. Vakitlerinin çoğunu bambu filizleri ve yapraklarını yiyerek geçirirler. Yaşamlarını devam ettirebilmeleri için ağırlıklarının yüzde on beşi kadar yemeleri gerekir. Nesli tükenmekte olan hayvanlar listesine alınan pandaların dünyada aşağı yukarı 2 milyon yıl kadar varlıklarını sürdürdükleri tahmin edilmektedir.","stem":"Yukarıdaki paragraftan hangisi kesinlikle çıkarılamaz?","options":["Bambu ormanlarının olduğu yerlerde yaşamlarını sürdürüler.","Pandalar nesli tükenen hayvanlar listesinde yer almışlardır.","Yaşamlarını sürdürebilmeleri için zamanlarının çoğunu yemek yiyerek geçirirler.","Yetişkin bir pandanın ağırlığı 120 kilogram olabilir."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg5-04-05","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"27 yıl sürdürdüğü doğa koruma çalışmalarıyla, alternatif Nobel olarak bilinen Doğru Yaşam Onur Ödülü’nün sahibi olan ve Birleşmiş Milletler tarafından “Orman Kahramanı” seçilen Toprak Dede Hayrettin Karaca, Türkiye’nin ilk özel arboretumunun(çok çeşitli ağaç ve ağaççıkların bulunduğu, bu amaçla özel olarak hazırlanmış botanik bahçesi) da kurucusuydu. O, ömrünü erozyonla mücadeleye ve verimli üst toprağın korunmasına adadı. Gelecek kuşaklara daha yaşanabilir bir dünya bırakmak için ağaçlandırma ve doğa eğitimlerinin önemine dikkat çekti. Kurduğu vakıf aracılığı ile Türkiye’nin dört bir yanında milyonlarca fidan toprakla buluşturuldu ve 3,5 milyondan fazla çocuk doğa eğitimi aldı. Yıllarca üzerinden çıkarmadığı ve onunla simgeleşen kırmızı süveterini “Param var ama harcamaya hakkım yok. Aldığımız her şeyin doğaya bir bedeli var.” diyerek açıklayan Karaca, sürdürülebilir bir yaşamın “tüketerek değil paylaşarak” mümkün olduğuna inanıyordu.","stem":"Bu metinden hareketle Hayrettin Karaca ile ilgili, I. Gayretli II. Doğasever III. Başarılı niteliklerinden hangilerine ulaşılabilir?","options":["I ve II.","I ve III.","II ve III.","I, II ve III."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg5-05-12","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Biz istediğimiz kadar, birey olmanın ve farklılıkların anlamından söz edelim. Aslında çoğu zaman herkesin seçtiğini seçiyor ve sevdiğini seviyoruz. Herkesten ayrı bir yanımız, farklı bir rengimiz kalmıyor böylece.","stem":"Bu parçada aşağıdakilerin hangisinden yakınılmaktadır?","options":["Ortak yaşam alanlarının artmasından","Bireyselleşmenin yaygınlaşmasından","Özgür ve özgün olma yanılgısından","Kişilerarası iletişimin azalmasından"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg5-05-17","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"En büyük sorunlarımızdan biri iletişimsizlik değil midir? Konuşan, yazışan ama birbirini anlamayan bir toplum hâline geldik. İnsanlara sorsanız herkes sohbet edebileceği birkaç dostu olduğunu söyler. Acaba öyle mi? Gerçekten sohbet etsek toplumda bu kadar üzgün insan olur muydu? Sadece konuşmak ya da mesajlaşmak değildir sohbet etmek. O, aynı zamanda karşıdakinin anlattıklarına dikkat kesilmek, muhatabı âdeta bir kitap gibi özenle okumaktır.","stem":"Bu metinde aşağıdakilerden hangisinin önemi vurgulanmaktadır?","options":["Konuşmanın","Dinlemenin","Yazmanın","Okumanın"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg5-05-19","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"İnsanın bir deneyimi sonrasında yaşadığı başarı veya başarısızlık hissi, o konuda kendine olan güvenini ve dolayısıyla daha sonra karşılaşacağı benzer tecrübelere vereceği tepkileri etkilemektedir. Örneğin bir alanda yaşadığı birkaç başarısızlığın etkisiyle o alanda ne yaparsa yapsın başarısız olacağını kabullenen bir kişi, mevcut durumu değiştirebilecek güce, yeteneğe ve şansa sahip olsa da başarma yolunda herhangi bir çaba göstermeyebilir.","stem":"Aşağıdaki durumlardan hangisi bu parçada anlatılanları örneklemektedir?","options":["Misafirlerine soğanlı menemen yapan Metehan’ın aldığı övgüler üzerine kendini mutlu hissetmesi","Yusuf’un, okul takımındaki 10 numaralı formanın kendisine uğur getirdiğine inanması","F klavye kullanmaya alışmış olan Neriman’ın Q klavye üzerinde yazı yazmakta zorlanması","Katıldığı resim yarışmasında üç yıl art arda derece alamayan Ali’nin sonraki yıl yarışmak istememesi"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg6-01-04","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Yemyeşil bir sabah... Her tarafta kuşlar uçuyor, buldukları azıcık su birikintilerinde yıkanıyordu. Güneş, masmavi gökyüzünde pırıl pırıl parlıyor; uzun geçen bir kıştan sonra var gücüyle doğayı ısıtmaya çalışıyordu. Etrafa türlü ağaçlardan insanı mest eden bir koku yayılıyor, ılık bir esinti âdeta yüzümü gıdıklıyordu.","stem":"Bu metinde aşağıdaki söz sanatlarından hangisi kullanılmıştır?","options":["Benzetme","Kişileştirme","Abartma","Konuşturma"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg6-04-05","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"1920’li yıllarda Kahramanmaraşlı seyyar dondurmacıların evlerinde ilkel koşullarda keçi sütü, salep ve kelle şekerle hazırlayarak dut ağacından yapılmış küleklerdeki tuz ve kar karışımıyla çevrili tulumbalarda tekerlemeler eşliğinde sattıkları dondurma, zaman içerisinde -özellikle 1980’li yıllardan itibaren- bileşim ve üretim teknolojisindeki hızlı gelişim sayesinde bugünkü kalite düzeyine erişmiştir. Günümüzde Maraş dondurması üstün kalite nitelikleri ve kendine özgü tüketimiyle (oda sıcaklığında yaklaşık 5–10 dakika bekletildikten sonra -12 ºC’de, çatal ve bıçakla) halkın beğenisini kazanmış, ulusal ve uluslararası gıda pazarlarında önemli bir yer edinmiştir.","stem":"Bu parçada Maraş dondurması ile ilgili; I. Nasıl tüketilir? II. İçeriğinde neler bulunur? III. Hangi ülkelere pazarlanır? sorularından hangilerinin cevabı vardır?","options":["I ve II.","I ve III.","II ve III.","I, II ve III."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg6-08-04","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Mehtap ve yakamoz, adına şarkılar bestelenmiş; seyrine doyum olmayan iki farklı tabiat olayı olsa da zaman zaman birbiri ile karıştırılır. Hâlbuki yakamoz, bir dalga ya da kürek hareketiyle uyarıldığında ışık saçan tek hücreli bir deniz canlısıdır. Denizin ateş böceği olarak da düşünülebilir. Mikroorganizma büyüklüğündeki on binlerce yakamozun bir araya gelerek oluşturduğu bu ışık gösterisini izleyebilmek için güneş, ay, şehir ışıkları gibi diğer ışık kaynaklarının yakamozların ışığını bastırmaması gerekir. Yakamoz oluştuğunda denizde uzun floresan ışıkları yanıyormuş gibi gözükür. Kelime olarak “ay ışığı” anlamına gelen mehtap ise bulutsuz gecelerde ayın deniz üzerinde yansımasıyla oluşan görüntüye denir.","stem":"Bu parçada aşağıdaki anlatım biçimlerinden hangisi ağır basmaktadır?","options":["Açıklayıcı","Betimleyici","Öyküleyici","Tartışmacı"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg6-08-06","grade":8,"topic":"Metinde yapı","difficulty":"Zor","outcome":"Metinde yapı","text":"Oğluna hayat dersi vermek isteyen bir baba birgün ona eski bir saat uzatır ve der ki: “Bu, dedemin saatidir. 200 yıldan fazla geçmişi olan bu saati sana vermeden önce bir saatçiye gidip saatin değerini sormanı istiyorum.” Oğlu saatçiye gittiğinde saatin eski püskü bir saat olduğunu ve ancak 5 lira edeceğini öğrenir. Babası bu kez saati antikacıya götürmesini ister. Antikacı saatin değerli bir parça olduğunu ve 5000 lira edebileceğini söyler. Babası “ Bu kez aynı saati müzeye götürmeni ve değerini sormanı istiyorum.” der. Denileni yapan oğul, müzede bu işte uzman biriyle görüşür. Uzman, saatin tarihi eser niteliğinde olduğunu ve müzeye vermeyi kabul ederse kendisine 1 milyon lira verebileceklerini söyler. Olanları babasına anlattığında babası ona “- - - -” der.","stem":"Bu metin düşüncenin akışına göre aşağıdaki cümlelerin hangisiyle tamamlanmalıdır?","options":["Saat, hayatımızın en vazgeçilmez eşyasıdır.","Antikacılar saatlerin değerini anlayamaz.","Değer görmek istiyorsan kıymetini bilenlerin yanında olmalısın.","Bir malın gerçek değerini farklı satıcılara sorarak öğrenebilirsin."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg6-08-07","grade":8,"topic":"Anlatım biçimleri","difficulty":"Zor","outcome":"Anlatım biçimleri","text":"Türkler ilk çağlardan bu yana birçok milletle komşuluk yapmış, zaman zaman onlarla iç içe yaşamış, yiyecek ve içecek kültürü alışverişinde bulunmuştur. Bunun sonucunda Türk mutfağı zengin bir kültür birikimiyle günümüze kadar gelmiştir. Geleneksel Türk mutfağının yaratıcılığı ve beğenileri, geleneksel değerleri, onu diğer kültürlerin mutfaklarından büyük ölçüde ayırmaktadır. Türk kahvesi de geleneksel Türk mutfağının vazgeçilmez unsurlarındandır. Gerek elde edilişi gerek yapılışı gerekse içimiyle diğer kahve çeşitlerinden oldukça farklı ve kendine özgüdür.","stem":"Bu durum kahve tüketimini de arttırmaktadır. Buna göre Türkiye’de 2012-2013 döneminde kişi başına 595 gram olan kahve tüketimi 2015-2016’da 920 grama ulaşmıştır. Bu metinde aşağıdaki düşünceyi geliştirme yollarından hangisi kullanılmamıştır?","options":["Örnekleme","Karşılaştırma","Sayısal verilerden yararlanma","Tanık gösterme"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg6-08-08","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Türkiye’de, bugüne kadar tespit edilen 10 kartal türünden biri olan kaya kartalı, oldukça geniş bir yayılış alanına sahiptir. Karadeniz ve Ege kıyıları ile İç Anadolu ve Güneydoğu Anadolu’nun güneyi hariç Türkiye’nin hemen her yerinde yaşadığı tespit edilen kaya kartalları, genellikle yüksek kayalıklarda ve ormanlık alanlarda yaşamayı tercih ediyor. Dağların özellikle sarp kayalık kısımlarını yuva yapan kaya kartalları çoğunlukla tavşan, sincap, tilki, yılan ve kaplumbağa gibi türlerle beslenir. Türkiye’de 2000-3000 çift kaya kartal popülasyonu olduğu tahmin ediliyor.","stem":"Bu metinde aşağıdaki sorulardan hangisinin cevabı vardır?","options":["Kaya kartallarının türleri nelerdir?","Kaya kartallarının fiziksel özellikleri nelerdir?","Kaya kartallarının diğer türlerden farkı nedir?","Kaya kartallarının yaşadığı bölgeler nerelerdir?"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg6-08-10","grade":8,"topic":"Metinde yapı","difficulty":"Zor","outcome":"Metinde yapı","text":"İşaretler doktrini, Avrupa’da 18. yüzyılın sonuna dek tıp alanında hastalıkların tedavisi için mucize bir çözüm olarak düşünülüyordu. Doktorlar, bir hastayı tedavi etmek için hastalığın belirtilerine benzeyen otlar, besinler veya eşyalar kullanıyorlardı. Örneğin beyinle ilgili olduğunu düşündükleri hastalıkların tedavisi için cevizden, kulakla ilgili hastalıklarda mantardan faydalanılıyordu. Günümüzde bazı Afrika kabilelerinde bu tedavi yöntemine hâlâ başvurulmaktadır. Ancak bu tür bir tedavi yönteminden çare beklemek pek akıllıca değildir çünkü- - - -","stem":"Bu paragrafta boş bırakılan yer aşağıdakilerin hangisiyle tamamlanabilir?","options":["Avrupalı doktorlar, benzerliğe dayalı bu tedavi biçimini yüzyıllar önce terk etmişlerdir.","bir olgunun ona benzer bir olguyla çözülebileceği inanışı bilimsel olarak geçerli değildir.","hijyenik olmayan şartlarda gerçekleştirilen tedaviler hastaya zarar verebilir.","farklı yiyeceklerin bu tür hastalıkların tedavisinde etkili olduğu ortaya çıkmıştır."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-lsg-lsg6-09-11","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Yemek yediğimden mi acıkıyorum, acıktığımdan mı yemek yiyorum, bilemedim. Gaziantep’e geldiğimden beri kendime bu soruyu soruyorum. Geleli üç gün oldu ama gezi planımda birinci sırada olan Zeugma’yı henüz görmedim. Bakırcılar Çarşısı’nı da dün sabah beyran çorbası içmek için girdiğim sokakta tesadüfen görüp çorbayı içtikten sonra, gezdim. Öğlen vakti Gaziantep Kalesi’nin yakınında yediğim patlıcan kebabı da Kale gezimin sebebi oldu. Katmer yemesem Cam Eserler Müzesini görmeyecektim. Tarihî Tren Garı gezisi, yeme içme planlarımın dışında gerçekleşen tek geziydi. Çünkü Gaziantep’e trenle geldim.","stem":"Bu metinde olayların oluş sırası aşağıdakilerin hangisinde doğru olarak verilmiştir?","options":["Beyran çorbası içme, Bakırcılar Çarşısı gezisi, patlıcan kebabı yeme, Kale gezisi, katmer yeme, Cam Eserler Müzesi gezisi, Zeugma Müzesi gezisi, Tren Garı gezisi.","Tren Garı gezisi, beyran çorbası içme, Bakırcılar Çarşısı gezisi, patlıcan kebabı yeme, Kale gezisi, katmer yeme, Cam Eserler Müzesi gezisi.","Beyran çorbası içme, Bakırcılar Çarşısı gezisi, patlıcan kebabı yeme, Kale gezisi, katmer yeme, Cam Eserler Müzesi gezisi, Tren Garı gezisi.","Tren Garı gezisi, beyran çorbası içme, Bakırcılar Çarşısı gezisi, patlıcan kebabı yeme, Kale gezisi, katmer yeme, Cam Eserler Müzesi gezisi, Zeugma Müzesi gezisi."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t1-020","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Şair, bir aydınlanma ve doğru olanın farkına varma hâlini ifade ettiği şiirinde, zamanın ve hayatın kıymetini bilmenin ve yaşama sevinçle bağlanmanın önemini kavradığını dile getirmektedir.","stem":"Bu parçada sözü edilen dizeler aşağıdakilerden hangisidir?","options":["Gökyüzünün başka rengi de varmış Geç fark ettim taşın sert olduğunu Su insanı boğar, ateş yakarmış Her doğan günün bir dert olduğunu İnsan bu yaşa gelince anlarmış","Yaşamak güzel şey doğrusu Üstelik hava da güzelse Hele gücün kuvvetin yerindeyse Elin ekmek tutmuşsa bir de Hele tertemizse gönlün Hele kar gibiyse alnın","Yaşım ilerledikçe daha çok anlıyorum Ne büyük nimet olduğunu ah ey güzel gün Boş yere üzülmekte mana yok, anlıyorum Kadrini bilmek lazım artık her açan gülün Şükretmek, türküsüne daldaki her bülbülün","Her mevsimiyle insanı ayrı ayrı saran Bunca güzelliği nasıl koyup gideceğiz Yaman çalacak o çalmayası saat yaman Geçmiş ola, bir kez yumuldu mu gözlerimiz"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t1-029","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Modern çağda şöyle bir problem var: Hep başka bir yerde olmak istiyoruz. Bulunduğumuz yer bize hiç mutluluk vermiyor. İnsan hep başka iklimlerin yeşil kırlarına özlem duyuyor. Bir yere tatile gittiğinde acaba buraya değil de başka yere gitseydim daha mı iyi olurdu, diye düşünüyor. Seçmediği her şey için sıkıntı hissetmeye başlıyor.","stem":"Aşağıdakilerden hangisi bu parçada sözü edilen görüşü desteklemektedir?","options":["Günümüzde her birimiz ağ vatandaşıyız artık. Ağa bir kez yakalanmayagörün, onun gerçekliği sizin gerçekliğiniz oluverir. Böylece sanal âlem, gerçek hayatımıza bulaşır ve gerçeklikle olan bağımız belirgin olmaktan çıkar.","Herkesin, önündeki ekrana baktığı bir çağda kimse diğerinin yüzüne bakmıyor. Hâlbuki bizi insan kılan şeylerden biri, muhatabımızın yüzünden, sesinden, duruşundan onu okuyabilmektir. İnsan olmak, hâlden anlamaktır.","Anlaşmak için zaman gerekir, zaman ve mekân. Konuşmanın yanında susmak, birbirinin söylediğine dikkat kesilebilmek, kalbini dostunun kalbine yaklaştırmak gerekir.","Yaşantı oburluğu içerisindeyiz. Ne kadar çok yaşantı tüketirsem o kadar mutlu olurum, şeklinde bir yanılgımız var. Hâlbuki sahip olduklarımızla da mutlu olabiliriz."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t1-048","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"(I) Basketbola benzer ilk oyunun Amerika’da Kızılderililer tarafından oynandığı belirtilmektedir. (II) Kızılderililerin oynadığı bu oyunda, yaklaşık 3 m yükseğe monte edilen bir sepete top atılır ve her sayıdan sonra sepetten elle çıkarılırdı. (III) Basketbolun bugünkü durumuna gelmesindeki ilk bilinçli çabalar, James Naismith tarafından 1891’de başlatılmıştır. (IV) Kış döneminde koşucuların sakatlanmalarını önlemek amacıyla yardımcı antrenman olarak yapılan basketbol, kısa bir sürede geniş kitlelerin ilgisini çekmiş ve zamanla popüler spor dallarından biri hâline gelmiştir. Basketbolun anlatıldığı","stem":"Bu parçada numaralanmış cümlelerle ilgili aşağıdakilerden hangisi yanlıştır?","options":["I. cümlede, en ilkel şeklinin kimler tarafından oynandığı anlatılmıştır.","II. cümlede, ilk olarak nasıl oynandığıyla ilgili bilgi verilmiştir.","III. cümlede, günümüzdeki şekline gelmesinde emeği geçen öncüden bahsedilmiştir.","IV. cümlede, ortaya çıkmasında koşucuların önemli bir katkı sağladığından söz edilmiştir."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t1-050","grade":8,"topic":"Konu ve başlık","difficulty":"Zor","outcome":"Konu ve başlık","text":"Sevgili Okurlarımız, Dergimizin bu sayısında ülkemizdeki denizlerde yaşayan canlılar, yuvadan düşen yavru bir kuş bulursanız yapmanız gerekenler, atmosfer optiğinin neden olduğu gök olayları, doğadan elde edilen boyalarla ilgili dikkat çekici yazılar bulacaksınız. Ayrıca yaz mevsiminin etkisini iyice hissettirdiği bu bunaltıcı günlerde heyecanla izlenen ve oldukça estetik hareketlerin yapıldığı bir su sporu olan “atlama”yı tanıyabileceğiniz yazımızın ilginizi çekeceğini düşünüyoruz. Tabii ki hem eğlenip hem öğrenebileceğiniz pek çok etkinlik de sayfalarımızda yer alıyor. Eklerimizde bu ay, hayvanlarla ilgili mesleklerden bazılarına yer verdiğimiz bilgi kartları ve çıkartmalı bir poster bulunuyor. Çıkartmalardaki canlıları, poster üzerindeki denizlerimize yapıştırabilirsiniz. Ancak öncelikle bu canlıların hangi denizlerimizde yaşadıklarını biraz araştırmalısınız. Bir derginin sunuş yazısından alınan","stem":"Bu parçadan hareketle aşağıdaki başlıklardan hangisinin bu dergide yer alması beklenmez?","options":["Atlama Havuzunda Antrenmandayız!","Buzul Erimesinin İnsanlara Etkisi","Hayvanlar Nasıl Muayene Edilir?","Atmosferdeki Gazların Renkli Oyunu"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t1-052","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Ben ki atalarımın sözünü kulağıma küpe ettim. Çünkü bilirim ki tecrübe eden, her birimizden daha bilgilidir. Görüp geçiren, bir tutulur mu kendi kabuğuna kapanıp kalanla? Tutulmaz elbet! Gel, sen sözümü yabana atma; altın ile bir tut bilge kelamını. Âlimin sözü bilgisiz için göz olur. Dinlemeyi bilirsen bak nasıl açılacak gözün, kulağın ve ruhun. Dilin daima tatlı, gözün pek olsun. Kulağın çift, ağzın tek olsun.","stem":"Bu parçada, I. Âlim unutmuş, kalem unutmamış. II. Az söyle, çok dinle. III. Ulu sözü dinlemeyen, uluyakalır. atasözlerinden hangilerinin içeriğiyle örtüşen öğütler verilmiştir?","options":["Yalnız I","Yalnız II","I ve III","II ve III"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t2-013","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Kişinin bazı olay ve durumlar karşısında kararsızlık yaşaması çatışmaya neden olur. Bu durum üç şekilde ortaya çıkabilir: Yaklaşma-Yaklaşma Çatışması: Birey, yapmak istediği iki şey arasında kararsızlık yaşar. Futbol oynamayı ve konsere gitmeyi seven birinin aynı saatte gerçekleşen bu iki etkinlik arasında kararsızlık yaşaması, bu çatışma türüne örnektir. Yaklaşma-Kaçınma Çatışması: Birey, bir şeye karşı istek duyar ancak bu istek, bireyin hoşuna gitmeyen bir durumu ortaya çıkarır. Dondurma yemek isteyen birinin, boğazı ağrıdığı için yemekten çekinmesi bu çatışma türüne örnektir. Kaçınma-Kaçınma Çatışması: Birey, istemediği iki durumdan birini seçmek zorunda kalır. Diş tedavisinden korkan birinin bu ağrıyı çekmek ile doktora gitmek arasında bir seçim yapma durumunda kalması, bu çatışma türüne örnektir.","stem":"Aşağıdaki atasözlerinden hangisi bu metinde sözü edilen çatışma türlerinden herhangi biriyle ilgili değildir?","options":["Ya bu deveyi gütmeli ya bu diyardan gitmeli.","Gülü seven dikenine katlanır.","Kır atın yanında duran ya huyundan ya suyundan...","Ne yârden geçilir ne serden."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t2-020","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Türkiye Büyük Millet Meclisi Müzesine giden bir öğrencinin, ziyaret ettiği bazı bölümlerle ilgili izlenimleri şunlardır: Bu odadaki sıralarda milletvekillerinin oturduğunu hayal edip yeni kurulan ülkenin o günkü atmosferinde nelerin görüşüldüğünü düşünmek oldukça heyecan vericiydi. Gezdiğim başka bir bölümde yerli ve yabancı basın-yayın organlarının farklı olaylarla ilgili manşetlerini okuyarak o dönemin izlerini sürdüm âdeta. Mustafa Kemal Atatürk’ün dürbünü, gömleği ve kravatının sergilendiği oda ise beni oldukça duygulandırdı. Bu izlenimlerden hareketle söz konusu öğrencinin, müzenin","stem":"Aşağıdaki bölümlerinden hangisini gezdiği söylenemez?","options":["Girişin Sağ Tarafındaki İkinci Oda Buradaki ışıklı pano ve vitrinlerde hukuk alanındaki düzenlemeleri; uluslararası takvim, saat, tartı ve ölçülerin kullanılmaya başlanmasını; yeni Türk harflerinin kabulünü; Türk Hava Kurumu, demir yolları, ekonomi ve sanayi ile ilgili gelişmeleri anlatan gazete kupürleri ve fotoğraflar sergilenmektedir.","Girişin Sol Tarafındaki İkinci Oda ‟İdare Heyeti” olarak kullanılan bu odada Cumhuriyet’in ilanından günümüze kadar basılan kâğıt ve madenî paralar, pullar ve madalyonlar sergilenmektedir.","Meclis Toplantı Salonu Bu salon, Cumhuriyet’in ilk yıllarından itibaren gerçekleştirilen büyük atılımların karar merkezi olarak birçok konuşmaya sahne olmuş, tarihî değeri yüksek bir mekândır.","Girişin Sağ Tarafındaki Üçüncü Oda Burada Türk Tarih ve Türk Dil Kurumlarının kuruluşu, Montrö Boğazlar Sözleşmesi, tarım, arkeoloji ve güzel sanatlarla ilgili gelişmeler, Türk kadınına seçme ve seçilme hakkının verilmesi fotoğraflarla ve Atatürk’ün sözleriyle anlatılmakta, Atatürk’ün bazı özel eşyaları ve el yazısı örnekleri sergilenmektedir."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t2-022","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Ayşe, Burhan, Cenk, Deniz, Ebru ve Ferhat’tan oluşan yeşil, mavi ve beyaz takım “pas atma” oyunu oynayacaktır. Oyun ile ilgili şunlar bilinmektedir: • Her takımda ikişer oyuncu vardır. • Beyaz takım, mavilere; maviler, yeşillere ve yeşiller de beyazlara pas atacaktır. • Cenk, Ebru’ya; Deniz, Ayşe’ye; Burhan ise Ferhat’a pas atacaktır. • Ayşe yeşil takımdadır. • Deniz ve Ferhat aynı takımdadır.","stem":"Bu bilgilerden hareketle aşağıdakilerden hangisi söylenebilir?","options":["Ayşe ile Cenk aynı takımdadır.","Burhan ile Ebru farklı takımdadır.","Deniz, yeşil takımdadır.","Ferhat beyaz takımdadır."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t2-023","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Günümüzde kitaplar, bir tüketim nesnesi olarak sunuluyor ve okur tarafından da öyle algılanıyor. Kitabın, yaşamını kolaylaştırmasını ya da ihtiyacını hemen karşılamasını bekliyor okur. Kitap tanıtım yazıları da bu gereksinimi karşılamak üzere hazırlanıp âdeta bir satış tekniği olarak kullanılıyor.","stem":"Aşağıdakilerden hangisi bu metinde eleştirilen türde bir kitap tanıtım yazısı değildir?","options":["Bu roman, “İncecik bir kitaba, tarihin en büyük acılarını sığdırmak mümkün müdür?” sorusunun cevabı niteliğini taşıyor. Sembolik ve ders verici anlatımıyla savaşın tüm yıkıcılığını ortaya koyuyor.","Bu kitap; insanın, elindeki en büyük gücü nasıl kullanması gerektiğini, inancın ve düşüncenin neler yapabileceğini söylerken kişinin, kendisi ile bağlantıya geçmesini de sağlıyor.","Bu eser, insanın toplum içindeki yalnızlığını ele alıyor. Yazarın, büyük şehirlerde yaşayan yalnız bireylerin psikolojisini çözümleme çabasına tanık oluyoruz.","Bu yapıt, sizi kendinizi bulmaya çağırıyor. Bu yapıtla duygu dünyanızın başrolü olan benliğinize geri dönecek ve kendinize tüm içtenliğinizle “Hoş geldin!” diyeceksiniz."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t2-042","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Bu bilgilere göre aşağıdakilerden hangisi sözü edilen vücut tiplerinin beş günlük egzersiz grafiğidir? Süre Süre Yavaş Yavaş (dk) (dk) Tempolu Tempolu Yoğun Yoğun Günler Günler B C A B C A B C A B C A B C B C A B C A B C A B C A B C Pazartesi Salı Çarşamba Perşembe Cuma Pazartesi Salı Çarşamba Perşembe Cuma Süre Süre Yavaş Yavaş (dk) (dk) Tempolu Tempolu Yoğun Yoğun Günler Günler B C A B C A B C A B C A B C B C A B C A B C A B C A B C Pazartesi Salı Çarşamba Perşembe Cuma Pazartesi Salı Çarşamba Perşembe Cuma 43. Bu","stem":"Metne göre aşağıdakilerden hangisi söylenemez?","options":["A vücut tipine sahip kişiler salı, B vücut tipine sahip kişiler çarşamba günü koşu egzersizi yapabilir.","A ve C vücut tipine sahip kişiler haftanın aynı günleri mekik ve barfiks egzersizleri yapabilir.","B vücut tipine sahip kişiler perşembe günü yürüyüş ve aerobik yapabilir.","C vücut tipine sahip kişiler salı günü yüzebilir ve voleybol oynayabilir."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t2-046","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Osman Hamdi Bey, Fransız Sanatçılar Derneğinin Paris’te düzenlediği sergide yer almak üzere bir tuval üzerine yağlı boya tekniğiyle yaptığı “Kaplumbağa Terbiyecisi” adlı tabloyu -sergideki asıl adı “Kaplumbağalı Adam”dır- Japonya’daki kaplumbağa terbiyecilerinden söz eden bir yazıdan esinlenerek oluşturmuştur.","stem":"Bu cümleden hareketle “Kaplumbağa Terbiyecisi” adlı tablo ile ilgili aşağıdakilerden hangisi söylenebilir?","options":["İlham kaynağı, Osman Hamdi Bey’in okuduğu bir yazıdır.","Birden fazla sergide farklı adlar kullanılarak sergilenmiştir.","Osman Hamdi Bey, diğer tablolarından farklı bir teknikle yapmıştır.","Japon kaplumbağa terbiyecilerini anlatmaktadır."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t2-051","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Yunancada “yaşam” anlamına gelen “bios” ve “taklit” anlamına gelen “mimesis” sözcüklerinden oluşan biyomimikri, tasarım yaparken ve yenilikçi teknolojiler geliştirirken doğadan esinlenmek olarak tanımlanabilir. Biyomimikri; mimari, yapay zekâ, robotik, endüstri, ulaşım gibi alanlarda kullanılan birçok ürünün, kısaca günümüz teknolojisinin temelini oluşturur. Bu","stem":"Metne göre aşağıdakilerden hangisi biyomimikriye örnek olamaz?","options":["En az malzemeyle en fazla yer inşa edilebilmesi amacıyla bal peteklerinin arılar tarafından altıgen şeklinde yapılması","Dalgıç giysilerinin, köpek balıklarının hızlı yüzmelerini sağlayan derilerinden ilham alınarak geliştirilmesi","Ayçiçeğinin güneşe doğru yönelme hareketinden yola çıkılarak gölgeli ve güneşli alan arasındaki sıcaklık farkına göre hareket eden güneş panellerinin üretilmesi","Geko kertenkelesinin ayağının altında bulunan ve tırmanmasını kolaylaştıran tüy benzeri dokudan hareketle farklı yüzeylere kolaylıkla tırmanabilen robotların yapılması"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t2-059","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Bir insanı dinleyerek anlarsınız, dinleyerek ondan yeni bir şeyler öğrenirsiniz. Halk arasında “- - - -” diye bir söz vardır ki dinlemenin konuşmadan yeğ olduğunu vurgular. Bizler muhatabımıza ne kadar iyi kulak verirsek onu o kadar iyi anlarız. Hâlbuki “- - - -” sözünün aksine pek çoğumuz; bırakın anlamayı, karşımızdakini iki cümle bile dinlemeden onunla tamamen farklı düşüncelere sahip olduğumuzu iddia ederiz. Gerçek dinleme tüm peşin hükümleri bir kenara bırakmakla olur. Şu sözü duymuşsunuzdur: “- - - -” Ön yargısız bir buluşma için muhteşem bir reçete! Kafamdakileri bir kenara bırakıp açık bir bilinçle yanına geleceğim ve senin bana öğretmeni bekleyeceğim.","stem":"Aşağıdaki sözlerden hangisi bu metindeki boşluklardan herhangi birine getirilemez?","options":["Tatlı dil, yılanı deliğinden çıkarır.","Allah; insana iki kulak, bir ağız vermiştir.","Ben bensiz geleyim, sen de sensiz gel.","Bilmek için anlamak, anlamak için dinlemek gerekir."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t2-063","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Ney dersi verdiğim dönemlerde, genç bir neyzen adayı ziyaretime gelmişti. Sesinin kendisini büyülediğini belirttiği bu enstrümanı öğrenmeyi çok istediğini söyledi. Öncelikle dersimizi dinlemesini ve dersimizin onun isteklerini karşılayıp karşılamadığını görmesini teklif ettim. Sonuna kadar sabırla takip etti. Nihayetinde dersi nasıl bulduğunu sorduğumda düş kırıklığına uğradığını çünkü nota öğrenmenin sanatta özgürlüğü engelleyeceğini anlatmaya başladı. Ben de sadece nota değil aynı zamanda usul ve makam bilgisi de anlattığımızı ifade ettim ve ekledim: “Sanattaki ilkeler, akarsuların önündeki barajlar gibidir. Akarsuları kontrol altına almazsanız ya kurak günlerde susuz kalırsınız yahut tarlanızı sel basar.”","stem":"Aşağıdaki sözlerden hangisi, yazarın bu parçada savunduğu düşünceyi desteklemektedir?","options":["Sanat, etrafı kurallarla çevrili bir adada serbestçe oynamaktır.","Sanat, ruhun dışa vurarak kendini gösterme ihtiyacından doğar.","Sanat, sanatçıdaki karşı konulmaz üretme arzusuyla ortaya çıkar.","Sanat, özgürlükle ne kadar beslenirse o kadar hızlı gelişir."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t3-015","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"(I) Gelişim, insanın en temel ihtiyaçlarından biridir. (II) Ancak günümüzde bilgeliğin yerini bilgi, oyunun yerini yarışma aldığı gibi maalesef gelişimin yerini de başarı almış durumda. (III) Hâlbuki her gelişim bir başarıyken her başarı bir gelişim değildir. (IV) Kişi, ehliyet sınavından iyi bir puan alabilir ama bu, onun öğrendiği ve geliştiği anlamına gelmeyebilir.","stem":"Bu parçada numaralanmış cümlelerle ilgili aşağıdakilerden hangisi söylenemez?","options":["I. cümlede karşılaştırma yapılmıştır.","II. cümlede olumsuz bir eleştiri vardır.","III. cümlede şarta bağlı bir durum söz konusudur.","IV. cümlede örneklemeden faydalanılmıştır."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t3-027","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Öğrenmenin aşamalarından bazıları şunlardır: • Bilmeme hâli: Neyi bilmediğini bilmez. • Öğrenmenin devam etmesi: Ne olduğunu bilir ancak yapamaz. • Ustalık: Otomatik olarak yapar.","stem":"Aşağıdakilerden hangisi, bu metinde sözü edilen öğrenme aşamalarından herhangi birine örnek olamaz?","options":["Telefonun video kırpma özelliğinin bilinmesine karşın bu özelliğin kullanılamaması","Bir türkünün, notalara bakılmaksızın bağlama ile kolayca çalınması","Babasının oltayla balık tuttuğunu gören bir çocuğun balık tutmaya çalışması","Bilgisayarın varlığından haberi olmayan birinin, onu açma konusunda da bilgisinin olmaması"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t3-041","grade":8,"topic":"Konu ve başlık","difficulty":"Zor","outcome":"Konu ve başlık","text":"Üç doğa kâşifi, aşağıdaki bilgileri internette sürekli takip ettikleri forum (toplu tartışma) sitesinde yer alan bir başlık altında paylaşmıştır. • Ülkemizde de bulunan fener balıkları denizlerin derinliklerinde yaşıyor. Bu balıklar, avlanmak için sırtlarında bulunan uzun dikeni kullanıyor. Bu dikenin ucunda ışık üreten bakteriler bulunuyor. Fener balığı bu özel dikeni tıpkı bir olta gibi kullanarak çeşitli yönlere hareket ettirebiliyor. Dikenin ucundaki ışığı besin sanıp ona yaklaşan balıklarsa fener balığına av oluyor. • Orkide peygamberdeveleri Güneydoğu Asya’da yaşıyor. Minik böceklerle beslenen orkide peygamberdevelerinin avlanmak için uyguladığı yöntem, kendilerini orkideye benzetmek. Bir dalın, yaprağın ya da çiçeğin üzerine konan peygamberdevesi normalden biraz farklı durunca tıpkı bir orkideye benziyor. Bu sayede onu orkide sanıp yaklaşan böcekleri kolayca avlıyor. • Yaşayan kaya adı verilen ve Doğu Afrika’da görülen bir balık türü, avını kendine çekebilmek için ölü taklidi yapıyor. Bu balık, kendini dibe bırakıyor ve avı tuzağa düşene kadar bu biçimde bekliyor. Ölü olduğunu sanan küçük balıklar ona yaklaşınca da saldırıya geçiyor ve onları yakalıyor.","stem":"Bu bilgilere göre aşağıdakilerden hangisi sözü edilen forum sitesindeki başlık olmaya en uygundur?","options":["Tropik Suların Garip Sakinleri","Saklanmayı Seven Hayvanlar","Şaşırtıcı Avlanma Yöntemleri","Hayvanlar Kendini Nasıl Savunur?"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t3-045","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Aynı yoldan, aynı hızla gidilmesine rağmen dönüş yolculuğunun gidişten kısa sürdüğü hissedilebilir. İlk olarak 1950’lerde tespit edilen bu duruma “dönüş yolculuğu etkisi” denir. Dönüş yolculuğu etkisi, gidiş esnasında aşinalık kazanılan yolun dönüşte daha kısa algılanması temeline dayanıyor. Zaman algısına yönelik çalışmalar da bu temele dayanak oluşturuyor. İlk defa tecrübe edilen bir durumda bilinmedik uyaranların etkisiyle zaman daha yavaş akıyormuş gibi algılanır. Dolayısıyla dönüş yolculuğunun süresine dair tahminler, gidiş yolcuğunun süresine dair tahminlere kıyasla gerçek yolculuk süresine daha yakındır.","stem":"Bu metinle ilgili aşağıdakilerden hangisi söylenemez?","options":["Bir kavramın tanımlaması yapılmıştır.","Ele alınan düşüncenin gerekçelerine yer verilmiştir.","Karşılaştırmadan yararlanılmıştır.","Öne sürülen fikirler örneklendirilmiştir."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t3-049","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Medya okuryazarlığı, kitle iletişim araçlarının verdiği mesajları doğru kavrayabilmeyi ve gerçek dünya ile medya dünyası arasındaki sınırı fark edebilmeyi sağlar. Medya okuryazarlığının bireylere kazandırdığı bazı beceriler şunlardır: I. Erişim becerisi: Bilgiye gazete, televizyon vb. medya araçlarından ulaşabilmektir. II. Çözümleme becerisi: Bilgilerin doğruluğunu, yanlışlığını, eksikliğini veya fazlalığını tespit edebilmektir. III. Değerlendirme becerisi: Bilgilerin özünü, önemini, nitelik ve niceliğini belirleyebilmektir. IV. Üretim becerisi: Bilgi ve mesajları kişinin kendisinin üretebilmesi ve yayabilmesidir. Bu","stem":"Metne göre, numaralanmış medya okuryazarlığı becerilerine örnek olabilecek davranışlar aşağıdakilerin hangisinde doğru eşleştirilmiştir?","options":["I. İnternette bir konuyla ilgili araştırma yapmak Bir haberde yer alan fotoğraftaki hileleri saptamak II. Yeni bir haber sitesi kurmak III. IV. Bazı televizyon programlarının çocuklar üzerindeki etkisi hakkında yorum yapmak","İnternette bir konuyla ilgili araştırma yapmak I. Bir haberde yer alan fotoğraftaki hileleri saptamak II. Bazı televizyon programlarının çocuklar üzerindeki etkisi hakkında yorum yapmak III. Yeni bir haber sitesi kurmak IV.","Bir haberde yer alan fotoğraftaki hileleri saptamak I. İnternette bir konuyla ilgili araştırma yapmak II. Bazı televizyon programlarının çocuklar üzerindeki etkisi hakkında yorum yapmak III. Yeni bir haber sitesi kurmak IV.","I. Bir haberde yer alan fotoğraftaki hileleri saptamak İnternette bir konuyla ilgili araştırma yapmak II. Yeni bir haber sitesi kurmak III. IV. Bazı televizyon programlarının çocuklar üzerindeki etkisi hakkında yorum yapmak"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t3-055","grade":8,"topic":"Yardımcı düşünce","difficulty":"Zor","outcome":"Yardımcı düşünce","text":"İSTİKLAL ŞAİRİ: MEHMET AKİF ERSOY Vefatının 86. yılında yâd ediliyor. Ödül olarak verilen parayı bir hayır kurumuna bağışlamıştır. Birinci Büyük Millet Meclisinde Burdur 20 Aralık’ta İstanbul’da dünyaya geldi. milletvekili oldu. 27 Aralık’ta Beyoğlu’ndaki Mısır Ortaokulu bitirdikten sonra dönemin Apartmanı’nda hayata gözlerini yumdu. Ankara’nın Hamamönü semtinde bulunan gözde okullarından Mülkiye İdadisine \"Tacettin Dergâhı\"na yerleşti. kaydoldu. Bilgi Notu Para ödülü verileceği için İstiklal Marşı * \"İstiklal Marşı\" Millî Mücadele’nin amacını ve Mülkiye İdadisini bırakıp Ziraat ve Yarışması'na katılmayan şair, yakın çevresinin milletimizin karakterini ortaya koyan somut bir Baytar (Veteriner) Mektebinde eğitime ısrarı üzerine İstiklal Marşı'nı yazmayı kabul belgedir. Bu marşta Türk milletiyle özdeşleşen başladı. etti. vatanseverlik, bayrak sevgisi, özgürlük, yiğitlik, şehitlik gibi değerler vurgulanmaktadır. İstiklal Marşı, Mustafa Kemal Atatürk’ün * İlk sayısı 27 Ağustos’ta yayımlanan Mehmet Akif Ersoy, İstiklal Marşı için \"Benim değil, başkanlığını yaptığı Meclis görüşmelerinde Türk milletinin eseridir.\" diyerek millî marşımızı \"Sırat-ı Müstakim\" dergisinin başyazarı 6 şiirle birlikte Meclisin seçimine sunuldu ve \"Safahat\" adlı eserine almamıştır. oldu. 12 Mart'ta millî marş olarak kabul edildi.","stem":"Bu metinden Mehmet Akif Ersoy’la ilgili aşağıdakilerin hangisine ulaşılamaz?","options":["Farklı türlerde eserler kaleme aldığına","İstiklal Marşı’nı kendi eseri olarak görmediğine","Birinci Büyük Millet Meclisinde görev yaptığına","İstiklal Marşı’nda Kurtuluş Savaşı’nın özünü yansıttığına"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t4-015","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Kudüs Şairi” ” Nuri Pakdil “Suskunluğu, tırnaklarımın altında bir tahta kıymığı gibi taşıyorum.” Pakdil, 1984 yılına kadar Harikalar Tablosu (çeviri şiir), Umut (oyun), Kahramanmaraş’ta dünyaya geldi. Sükût Suretinde (şiir) ve Batı Notları’nın (gezi) aralarında bulunduğu pek çok kitap çıkardı. “Büyük Doğu” ve “Diriliş” dergileriyle güçlü bağlar kurdu. “Otel Gören Defterler” başlıklı altı kitaptan oluşan deneme serisi Türk edebiyatında “Yedi Güzel Adam” okuyucuyla buluştu. olarak bilinen sanatçılardan Rasim Özdenören, Erdem Bayazıt ve Akif İnan ile birlikte “Edebiyat” 2013’te Kültür ve Turizm Bakanlığı dergisini yayımlamaya başladı. Kültür Sanat Büyük Ödülü’ne, 2014’te ise Necip Fazıl Saygı “Edebiyat” dergisinin çevresinde Ödülü’ne layık görüldü. çok sayıda yeni şair ve yazar yetişti.","stem":"Bu metinde Nuri Pakdil ile ilgili, I. Hangi türde eserler verdiği II. Fikir hayatının şekillenmesinde kimlerin etkili olduğu III. Kendisine niçin ‟Kudüs Şairi” dendiği bilgilerinden hangilerine değinilmiştir?","options":["Yalnız I","Yalnız II","I ve III","II ve III"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t4-017","grade":8,"topic":"Konu ve başlık","difficulty":"Zor","outcome":"Konu ve başlık","text":"Antroposen adı verilen yeni çağın en belirgin özelliği, ona jeolojik faaliyetlerden çok, insanların yol açmış olmasıdır. - - - -","stem":"Bu cümlenin ardına anlam akışına göre, I. Antroposen Çağı’nda gezegenin insan eli değmemiş köşeleri gitgide azalırken yerleşim merkezleriyle diğer canlıların paylaştığı kırsal arasında var olduğuna inanılan kültür-doğa ayrımı ortadan kalkıyor. II. Canlılar ile makinelerin, doğal ve yapay zekânın iç içe geçtiği bu çağın gözle görünür sonuçlarından en dikkat çekeni, Pasifik Okyanusu’ndaki ‟Yedinci Kıta” adı verilen devasa atık yığınıdır. III. Farklı bir jeolojik çağa girildiği konusunda dünyadaki pek çok bilim insanı aynı fikri taşımaktadır. cümlelerinden hangileri getirilebilir?","options":["Yalnız I","I ve II","II ve III","I, II ve III"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t4-026","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Ülkemizde sağlık giderlerinin %60’ı ilaç harcamalarından oluşuyor. Bu oran Avrupa ülkelerinde %15 civarında. Eczanelerdeki ilaçların ortalama %7’si kullanım süresi dolduğu için çöpe atılıyor. Evlerde antibiyotiklerin %44’üne hiç dokunulmuyor, diğer ilaçların ise %60’ının kullanım tarihi, kutusu dahi açılmadan sona eriyor. Bu açıklamaya göre, I. Son kullanım tarihi geçmemiş ve kullanılmayan ilaçlar için toplama merkezleri oluşturulması II. İlaç tüketimi konusunda toplumun bilinçlendirilmesi III.","stem":"İlaç tanıtım yazılarının (prospektüs) dikkatle okunması fikirlerinden hangileri metinde sözü edilen soruna yönelik bir çözüm olabilir?","options":["Yalnız I","I ve II","II ve III","I, II ve III"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t4-035","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Büyük firmalar bir yerde mağaza açmadan evvel ön araştırma yapar. Bu araştırmada mağazanın açılacağı bölgeden günde kaç kişinin geçtiği; geçenlerin yaşı, cinsiyeti ve beğenileri ile ilgili veriler toplanır.","stem":"Bu parçanın sonuna “Tıpkı bunun gibi, bir konuşmacının da konuşmasından önce dinleyicilerin nelere ilgi duyduğu noktasında titizlik göstermesi gerekir.” cümlesi getirilirse aşağıdakilerden hangisi yapılmış olur?","options":["İlişkilendirme","Onaylama","Eleştiri","Betimleme"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t4-045","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Bu sabah erkenden kalktı. Her zamanki gibi elini yüzünü yıkayıp saçlarını taradı. Güneş, yeni yeni gösteriyordu yüzünü. Pencereyi açıp derin bir nefes aldı. Güneşin doğuşuyla aydınlanan gökyüzünü ve ufku taradı uzun bir süre. Sonra bahçenin ayrık otları ve taşlarla dolu toprağına takıldı gözleri. Dışarı çıkarak kullanacağı malzemeleri hazırladı özenle. Bahçenin bir bölümünü dikkatlice belledi. Toprağı tırmıkla tarayıp taşları ve otları ayırdı.","stem":"Bu parçada “taramak” sözcüğü aşağıdaki anlamlarından hangisini karşılayacak şekilde kullanılmamıştır?","options":["Bir şeyin tellerini birbirinden ayırıp karışıklığını gidermek","Kafasından geçirmek, belli belirsiz düşünmek","Bir şeyin içindeki gereksiz maddeleri ayıklamak","Dikkatle bakmak, süzmek"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t4-056","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"(l) Şu köşedeki kıvırcık saçlı çocuğun, kütüphaneye önemli bir sınava hazırlanmak için geldiğini düşünüyorum. (ll) Sabah erkenden gelip köşedeki masaya oturuyor, akşama kadar da önündeki kitapları okuyor. (lll) Şu orta masada çalışan kısa saçlı kadın, kalın kitaplarını masaya yığıyor; her birine hızlıca bakıp defterine notlar alıyor. (lV) Kalın bir kitabın, dergilerde olduğu gibi hızla karıştırılıp içeriği anlaşılamayacağına göre belli ki bir yerlerde paylaşmak üzere dikkat çekici sözler arıyor.","stem":"Bu metinde numaralanmış cümlelerin hangilerinde yorum yapılmıştır?","options":["I ve III","I ve IV","II ve III","II ve IV"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t4-058","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Babam, elinde bir hediye paketiyle geldiğinde henüz dördüncü sınıfta okuyordum. Parlak, mavi hediye paketini heyecanla açıp içindeki kitabın kapağına dokundum. Beyaz bir zemin üzerinde küçücük bir dünya ve dünyanın üzerinde dallarında kıpkırmızı elmalar olan ufacık bir ağaç... Ufacık bir ağaç meyve verir mi hiç, diye düşündüm. Biraz araştırınca verebildiğini öğrendim. O gün fark ettim ki insan, her şeyi doğru değerlendirdiğini zannediyor.","stem":"Bu metinle ilgili aşağıdakilerden hangisi söylenemez?","options":["Mecazlı ifadeler vardır.","Betimleyici unsurlar kullanılmıştır.","Öyküleyici anlatımdan yararlanılmıştır.","Genellemeye yer verilmiştir."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t4-060","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Bir bilge, krala üç yüz milyon nefes hakkı kaldığını söylemişti. Kral, nefesini uzun süre tutabilmek ve ömrünü uzatmak için çok çalıştı. Son üç nefes hakkı kaldığında artık nefesini beş dakika tutabiliyordu. Önünde sadece on beş dakika, ardında bomboş bir hayat heybesi kalmıştı. Bu şekilde yaşayan ne çok insan var!","stem":"Bu parçada anlatılanları en iyi ifade eden dizeler aşağıdakilerin hangisinde verilmiştir?","options":["Dünü, yarını düşünmek hepimizin hatası Bugünü yaşamak varken bu neyin kaygısı, cefası","Kaynaşır birbirine gün olur zamanlar Geçmiş, gelecek birleşir tek kesitte","Bu rüzgâr her vakit böyle esmeyecek Gökte bulut, suda yelken, dalda çiçek","Elde görür hep hatayı kusuru Çünkü olmuş kibirinin esiri"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t4-069","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Anadolu’nun bir kasabasında, kitaplığı olan bir evde doğup büyüdüm. Sağlam bir bağ kurdum bu sayede kitaplarla. İlkokul ve ortaokulda girişken bir çocuktum, lise yıllarımda ise biraz içe dönüktüm. Kitaplarla aram hep iyiydi ama. Keyifsiz anlarımda kitaplarla moral bulurdum. Babam öğretmendi, onun kitapları da miras kaldı bana. Kendini bu sözlerle ifade eden bir kişiyle ilgili","stem":"Aşağıdakilerden hangisi söylenemez?","options":["Kitap okumayı sevmesinde yetiştiği ortamın etkili olduğu","Yazarlığı tercih etmesinde babasının rolünün bulunduğu","Sıkıntılı hissettiği zamanlarda kitaplara tutunduğu","Yaşamının bir döneminde sosyal ilişkilerinin zayıfladığı"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t4-076","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Gerçek hayatla sanat eseri arasında yakınlık arayanların, sanat eserini sanatçının hayatı ile açıklamaya çalışanların en büyük hatası sanat eserini gerçeği yansıtan bir ayna olarak görmeleridir. Bu hataya düşenler sanat eserinin alışılmış bir düzeni değiştirmekle, yeni bir anlayış, yeni bir dünya getirmekle yükümlü olduğunu göz ardı ederler. Hâliyle gerçek hayattan hareket ederek sanat eseriyle ilgili bir yargıya varmak, sanatçının hayatından işe girişerek eseri anlatmaya çalışmak hep yanlış bir sonuç vermiştir. Bu nedenlerden dolayı da sanat eseri bazı kimselerce, var olanı tespit etmeye yarayan basit bir araca dönüştürülmüştür.","stem":"Aşağıdakilerden hangisi bu metinde eleştirilen bir durumdur?","options":["Sanat eserleriyle ilgili olumsuz yorumların sanatın gelişimine engel olması","Sanat eserlerini eleştirenlerin tarafsız davranmaması","Sanat eseri değerlendirilirken sanatçının hayatından bağımsız düşünülmemesi","Sanatçıların, sanat eseriyle yeni bir hayat görüşü sunmamaları"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t5-011","grade":8,"topic":"Konu ve başlık","difficulty":"Zor","outcome":"Konu ve başlık","text":"İnternette yayımlanan yazılarda kullanılan başlıkların özgün olması çok önemlidir. Bu başlıklar okurun ilgisini çekecek şekilde oluşturulmalıdır. Aşağıda ilgi çekici başlık oluşturmayla ilgili bazı ipuçları yer almaktadır. Okuru yönlendiren emir cümleleri kullanılmalıdır. Saygı duyulan kişilerden söz eden başlıklar tercih edilmelidir. Kişisel bir deneyim anlatılarak hem merak uyandırılmalı hem de okurun empati kurması sağlanmalıdır. İki durumun karşılaştırılmasıyla oluşturulan başlıklar kullanılarak okuyucunun ilgisi çekilmelidir.","stem":"Aşağıdaki başlıklardan hangisi bu metinde verilen ipuçlarından herhangi biriyle ilişkilendirilemez?","options":["Bir Haftalık Orman Kampında Öğrendiklerim","Kahve mi, Çay mı: Ezelî Rakiplerin Sağlığımıza Etkisi","Koruyucu Kalkanımız: Dünya’nın Manyetik Alanı","Başarılı Olmak İstiyorsanız Önce Bunları Yapın"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t5-013","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Matematikteki “büyüktür (>)” işareti bugün sosyal medyada duygu ve düşüncelerini aktarmak isteyenler tarafından iki nesne, kişi vb. arasında karşılaştırma yapılırken yaygın olarak kullanılmakta; “>” işaretiyle beğeni, istek, destek, tercih anlamı ifade edilmektedir. Örneğin “Fatma’yı değil Ayşe’yi destekliyoruz, beğeniyoruz, tercih ediyoruz…” cümlesi yerine “Ayşe>Fatma” ifadesi kullanılıyor. Böylece “>” işareti “destekliyorum, beğeniyorum, tercih ediyorum...” anlamlarını karşılıyor. Sonuç olarak matematikte “büyüktür” anlamına gelen işaret, anlam genişlemesine uğrayarak sosyal medyada bambaşka anlamlarda kullanılıyor.","stem":"Bu parçada “>” işaretiyle ilgili, I. Sosyal medyada sıklıkla kullanıldığına II. Matematikteki kullanımının azaldığına III. Farklı anlamlar ifade ettiğine yargılarından hangilerine değinilmiştir?","options":["Yalnız I","I ve III","II ve III","I, II ve III"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t5-023","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Ben bir kitap kapağı tasarımına başladığımda ilk iş olarak kitabı okuyorum. Bir taraftan da yazarla kitabı hakkında yüz yüze görüşüyorum, yayına hazırlayan arkadaşımla kitabın içeriği ve olası kapak görselleri konusunda tartışıyor ve çalışmaya başlıyorum. Bu içerik çalışması dışında tabii ki kapak kâğıdının kalitesi ve kapakta oluşturduğum figürleri süsleme tarzımın da bana bu başarıyı getirdiğini düşünüyorum.","stem":"Bu metin aşağıdaki sorulardan hangisine karşılık söylenmiş olabilir?","options":["Kitap kapaklarının, kitabın içeriğiyle ilgili olması gerektiğini düşünüyor musunuz?","Kitap kapağı tasarımlarına ödül verilmesiyle ilgili neler söylemek istersiniz?","Yılın en iyi kitap kapağı tasarımcısı seçilmenizi neye bağlıyorsunuz?","Kitapların çok satılmasında kapak tasarımının etkisi var mıdır?"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t5-026","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Alışveriş sitelerinden birinde yer alan bir çantayla ilgili müşteri yorumları şunlardır: Fatma Görünüşünü ve kalitesini çok beğendim. Çocuğumun eşyalarını yerleştirmek için almıştım fakat içi beklediğim kadar geniş değil. Kumaşı kalın olmadığı için astarı olsaydı daha kullanışlı olurdu diye düşünüyorum. Cevapla Beğen Beğenme Ayşe Gayet güzel ve şık, ne çok büyük ne de küçük. Lisede okuyan kızım için aldım. Kumaşı ince, beş yıl önce aldığımız aynı marka çanta da öyleydi ama hâlâ sağlam. Rengini de çok beğendim. Cevapla Beğen Beğenme Hatice Çanta kısa sürede elime ulaştı. İçi oldukça geniş. Aldığımdan bu yana makinede iki kez yıkamama rağmen herhangi bir yıpranma olmadı. Cevapla Beğen Beğenme Elif Oğlum için aldım, çok beğendi. İçine her boy kitap sığıyor, okul çantası olarak da kullanılabilir. Renk seçeneği fazla olsa daha iyi olurdu. Hızlı teslimat için ayrıca teşekkür ederim. Cevapla Beğen Beğenme Bu çantayla ilgili yorumlarda","stem":"Aşağıdakilerden hangisine bütün müşteriler değinmiştir?","options":["Kumaşına","Teslimat süresine","Rengine","Boyutuna"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t5-030","grade":8,"topic":"Metinde yapı","difficulty":"Zor","outcome":"Metinde yapı","text":"Kimi kitaplar - - - - gibidir. Sanki her şey gözünüzün önünde olup bitmektedir. Bu yüzden Dostoyevski romanlarını unutamaz birçoğu. Kimi kitaplar - - - - gibidir. Her satırda bir gizem çıkar ortaya, insanda merak uyandırır. Bu yüzden “Sherlock Holmes” hep tutulur yastık altında. Kimi kitaplar ise - - - - gibidir, gelecekten haberler getirir. İçindeki çocuğu koruyabilen her büyüğü bu nedenle mutlu eder “Ay’a Seyahat”.","stem":"Aşağıdakilerden hangisi anlam akışına göre, bu parçada boş bırakılan yerlerden herhangi birine getirilemez?","options":["ilaç","bulmaca","tablo","zaman makinesi"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t5-031","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Leonardo da Vinci tarafından yapılan Mona Lisa, dünyanın en ünlü tablolarından biridir. Her yıl milyonlarca insan, Paris’teki Louvre (Lur) Müzesinde sergilenen bu eseri görmek için sıraya giriyor. Fakat 20. yüzyılın başlarında Mona Lisa tablosunu bilenlerin sayısı oldukça azdı. Ta ki tablo, bir sabah kayıplara karışana kadar… Polis, tablonun kayıp ilanlarını şehrin duvarlarına asarken dünya genelinde birçok gazete de bu haberi sayfalarına taşıyordu. Hâl böyle olunca milyonlarca insanın gözü bu olaya çevrildi. Fransızlar bu olaydan utanç duydu. İki yıl süren soruşturma neticesinde Mona Lisa’nın bulunduğunu duyan insanlar çok sevindi. Tablonun, ait olduğu yere asılmasının ardından sadece iki gün içerisinde yaklaşık bir milyon ziyaretçi onu görmek için Louvre Müzesine akın etti.","stem":"Bu parçaya göre “Mona Lisa”nın dünyaca ünlü bir tablo hâline gelmesinin asıl nedeni aşağıdakilerden hangisidir?","options":["Kaybolmasının, dünya genelinde dikkat çekmesi","Bulunma sürecinde polisin titizlikle çalışması","Fransızların, kayıp olayına çok üzülmesi","Bulunduktan sonra pek çok kişi tarafından ziyaret edilmesi"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t5-046","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"(I) Erzurumlu bir tanıdığınız varsa veya bir Erzurum evini ziyaret etme şansınız olduysa şeker makasını tanıyor olmalısınız. (II) Şeker makası, Erzurumluların ‘‘kıtlama’’ adını verdikleri sert şekeri kesmeye yarayan bir alet. (III) Erzurum insanı şekeri çaya atmaktansa ağzında tutmayı alışkanlık edindiğinden ortaya çıkmış bu makas. (IV) Ne zaman bu makasla karşılaşsam Erzurum’da yaşadığım güzel günleri anımsar, duygulanırım.","stem":"Bu metinde numaralanmış cümlelerle ilgili aşağıdakilerden hangisi yanlıştır?","options":["I. cümlede ihtimal anlamı vardır.","II. cümlede tanımlama yapılmıştır.","III. cümlede neden ilgisi vardır.","IV. cümlede bir beklenti dile getirilmiştir."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t6-014","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Bir günü daha eskitip anılarımızın arasına gönderdik. Solmuş bir gül yaprağı gibi dökülüp gitti geçmişe. Onu da kurutup özenle koyduk bir kitabın arasına.","stem":"Bu parçada “solmuş bir gül yaprağı” sözüyle aşağıdakilerden hangisi kastedilmiştir?","options":["Anılar","Gün","Kitap","Geçmiş"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t6-015","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Gezegenimizde kendi kulvarında birinci olan yerleri hiç merak ettiniz mi? İşte, karşınızda gezegenimizin rekortmen yerlerinden bazıları:","stem":"Bu cümlelerle başlayan bir metinde aşağıdakilerden hangisinin yer alması beklenmez?","options":["Uydu ölçümleri, dünyanın en sıcak yerinin 70 °C’yi aşan sıcaklığıyla Lut Çölü olduğunu ortaya koydu. İran’ın güneydoğusundaki bu çöl öylesine sıcaktır ki bilim insanları, önceleri burada canlıların yaşamasının olanaksız olduğunu düşünmüştü. Ancak akıllara sığmayan bu sıcaklığa rağmen çeşitli sürüngen ve örümcekler burada hayatta kalabiliyor.","Angel Şelalesi, 979 metre yüksekliğiyle dünyanın en uzun gökdelenini bile geride bırakır. Şelaleden akan su, havanın sıcak ve kuru olduğu dönemlerde tabana ulaşamadan buharlaşmaktadır. 18 Kasım 1933’te ABD’li bir pilot tarafından keşfedilen ve dünyanın en yüksek şelalesi olan Angel Şelalesi, aynı zamanda Venezuela’nın en ünlü turistik yerlerinden biridir.","Dünyanın en ilginç mağaralarından biri olan ve Lübnan’ın 18 km kuzeyindeki bir vadide bulunan Jeita Grotto Mağarası; ilginç kaya şekilleri ile ziyaretçilerini büyülüyor. İki kısımdan oluşan mağaranın alt kısmı 1836 yılında Reverend William Thompson tarafından, üst kısmı ise 1958 yılında Lübnanlı mağara bilimciler tarafından keşfedilmiştir.","Dünyanın en büyük adası olan Grönland, aslında üç ayrı adadan oluşur ve bu adalar kalın bir buz örtüsüyle birbirine bağlıdır. Kalınlığı yer yer 3 kilometreye varan bu buz örtüsü, altındaki karaya öylesine baskı yapar ki üç ada da deniz seviyesinin 300 metre altında kalır. Dünyada Antarktika dışında buz örtüsü görülen tek yer Grönland’dır."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t6-019","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Tereddüt, olumsuza yakın kararsızlık hâlidir. Kabulden çok, redde yakındır. Zamana yayılan her irade; kabulün düşmanı, reddin dostudur.","stem":"Aşağıdakilerden hangisi bu metinde sözü edilen tereddüt hâline örnek olabilir?","options":["Vitrindeki o gösterişli elbiseyi alıp almama konusunda bir an duraksadı. Aşağı tükürse sakal, yukarı tükürse bıyık… Asla yanlış bir şey yapmak istemiyordu.","Eğitimini nerede sürdüreceğiyle ilgili düşüncesi netleşmişti artık. Doğru veya yanlış, bir an önce karara varmak onu rahatlatmıştı.","Acele işe şeytan karışır, sözünün doğruluğuna hiçbir zaman itimat etmeyip yapılacak olanı hemen yapıverirdi.","Toplantıya yetişebilmesi için çok hızlı hareket etmesi ve vakit geçirmeden yola çıkması gerektiğini biliyordu."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t6-013","grade":8,"topic":"Yardımcı düşünce","difficulty":"Zor","outcome":"Yardımcı düşünce","text":"2023 yılı, ülkemizde Mevlâna Yılı ilan edildi. “Gel; ne olursan ol, yine gel!” çağrısıyla tüm dünyada yankı uyandıran, Anadolu topraklarında kalpleri sevgi ve şefkat hamuruyla yoğuran, büyük Türk düşünürü Mevlâna Celâlettin Rumi’nin hayatı, fikirleri ve eserleri asırlardır insanlığın yolunu aydınlatmaktadır. 13. yüzyılın başlarında Afganistan'ın Belh Dinî bilgilerden edebiyata, sağlıktan insan şehrinde doğdu. Moğol İstilası nedeniyle küçük ilişkilerine ve hayata dair pek çok konuya yer yaşlarda bu şehirden ayrıldı. Anadolu’nun bazı verdiği altı ciltlik “Mesnevi” adlı eseriyle şehirlerinde bir süre yaşadı. Anadolu’da millet olma şuurunu yerleştirmiştir. Anadolu Selçuklu Sultanı Alâattin Keykubat’ın Hayatını “Hamdım, yandım, piştim.” sözleriyle daveti üzerine Konya’ya göç etti. Belh’ten özetleyen Mevlâna, 17 Aralık 1273’te vefat etti. Konya’ya uzanan yolculuğunda uğradığı Ölüm onun için Allah’a kavuşmaktı. Bu nedenle şehirlerde çeşitli âlimlerden dersler aldı. vefat ettiği gün “düğün gecesi” anlamına gelen “Şebiarus” adıyla anılıyor.","stem":"Bu parçadan Mevlâna ile ilgili aşağıdakilerden hangisi çıkarılamaz?","options":["Farklı âlimlerden ilim öğrendiği","Evrensel mesajlarıyla insanlığa yol gösterdiği","Halka ilim öğretmesi için Konya’ya davet edildiği","Anadolu’da millî bilincin sağlanmasına katkı sunduğu"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t6-046","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"2023 yılında Türkiye’deki iki alan daha UNESCO Dünya Mirası Listesi’ne kaydedildi. Bu alanlardan ilki, Ankara’nın I Polatlı ilçesinde yer alan Gordion’dur. Geçmişte Friglerin başkenti olan Gordion’daki anıtsal yapılar, dönemlerinin II Anadolu’daki eşsiz örneklerini yansıtıyor. İkinci alan ise “Anadolu’nun Orta Çağ Dönemi Ahşap Direkli ve Kirişli Camileri”dir. Bu camiler, hipostil (sütunlarla desteklenen bir çatıya sahip salon) planlı anıtsal ahşap cami türünün Anadolu’daki en önemli örnekleridir. 13 ve 14. yy.larda inşa edilen bu yapılardaki ahşap kullanımı Türklerin Orta Asya III ve Anadolu’daki mimari üslubunu yansıtmaktadır. Herbiri İslam mimarlık tarihi açısından büyük öneme sahip IV olan bu camiler; Beyşehir Eşrefoğlu Camii (Konya), Sivrihisar Ulu Camii (Eskişehir), Afyonkarahisar Ulu Camii (Afyonkarahisar), Kasabaköy Mahmut Bey Camii (Kastamonu) ve Arslanhane Camii’dir (Ankara). Bu parçada numaralanmış sözlerin hangisinde yazım yanlışı yapılmıştır? 47. Halil İnalcık’ın kronolojik sıraya göre derlediği bazı makaleleri “Osmanlı Deniz Egemenliği” adlı eserde ilk kez toplu olarak okurla buluştu. Eser, kuruluşundan 17. yy. ortalarına kadar Osmanlının denizlerdeki varlığını, askerî ve teknik gelişimini ele alıyor. Halil İnalcık beş ana başlık altında topladığı makalelerinde Osmanlının Akdeniz ve Karadeniz’de nasıl büyük bir deniz gücü hâline geldiğine, Fatih Sultan Mehmet Devri sonrası denizcilik faaliyetlerine, Boğazlardaki egemenlik mücadelelerine ve Osmanlı deniz tarihine dair pek çok konuyu ayrıntılı biçimde inceliyor.","stem":"Bu parçadan “Osmanlı Deniz Egemenliği” adlı eserle ilgili, l. Osmanlı tarihini bazı yönleriyle ele almaktadır. ll. Halil İnalcık’ın kimi makalelerinin bir araya getirilmesiyle oluşturulmuştur. lll. Türk denizciliğinin gelişimini kapsamlı bir şekilde anlatan ilk eserdir. yargılarından hangilerine ulaşılabilir?","options":["Yalnız I","Yalnız III","l ve ll","ll ve lll"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t6-050","grade":8,"topic":"Konu ve başlık","difficulty":"Zor","outcome":"Konu ve başlık","text":"• Farklı yazı aletleri ve mürekkep kabının konulduğu yazı takımına divit, bunları yapan kişilere de divitçi adı verilir. Günümüze gelene kadar önce daktilo, ardından da bilgisayar ve akıllı telefon kullanımının yaygınlaşması bir yana kalemin bile az kullanılır hâle gelmesi bu mesleğin, tarihin sayfaları arasında yerini almasına neden olmuştur. • İstediğimiz ürünlerin kapımıza gelmesi sadece bugüne ait bir ayrıcalık değil. Geçmişte bir yerden bir yere gitmenin ve alışveriş yapmanın zor olduğu zamanlarda çerçiler, özellikle köylerde, eşek veya at üzerinde taşıdıkları ürünlerle ev ev gezerlerdi. Leğenden iğneye her çeşit tuhafiye ürününü ücreti karşılığında veya takasla satarlardı. Bugün ulaşım araçlarının gelişmesiyle bu iş alanı kaybolmak üzeredir. • Debbağlık, çeşitli ürünler yapmak için deriyi işleme zanaatıdır. Mesleğin atölyeleri, Fatih Sultan Mehmet Dönemi’nde ilk olarak İstanbul Kazlıçeşme’de kurulmuş ve debbağlık zanaatı yüzyıllarca devam etmiştir. Son derece özveri ve emek isteyen bir iş koludur. Bugün atölye ve fabrikalarda çeşitli makinelerle seri üretim yapıldığı için bu mesleğe artık rastlanmamaktadır.","stem":"Bu parçalara getirilebilecek ortak başlık aşağıdakilerden hangisi olabilir?","options":["Teknolojiye Yenik Düşen İş Alanları","Kaybolmaya Yüz Tutan El Sanatları","Osmanlı Dönemi’ndeki Zanaatlar","El Becerisi Gerektiren Meslekler"],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t6-051","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"“Büyük ve süslü çadır” anlamına gelen “otağ” sözcüğü, kaynağını “ateş” anlamındaki “od” sözcüğünden alır. Günümüzde otağ sözcüğü; evin bazı bölümlerinin adı olan “oda” ile ilişkili olsa da geçmişte “ateş yakılan yer, ocak” anlamında kullanılmıştır. Nitekim ilk anlamı “ateş yakmaya yarayan yer” olan ocak sözcüğünün karşılıklarından birinin “ev, aile, soy” olması bu bağlantıyı ortaya koymaktadır. Dilimizde aile hayatının devamına ve durumuna vurgu yapan “ocağı tütmek” deyimi yahut İstiklâl Marşı’nın “Korkma, sönmez bu şafaklarda yüzen al sancak; / Sönmeden yurdumun üstünde tüten en son ocak.” dizeleri Türk insanının yaşadığı yerde yanan ateşle kendi kaderi arasında derin ilişkiler kurduğunun göstergesidir. Bu metnin anlatımıyla ilgili","stem":"Aşağıdakilerden hangisi söylenebilir?","options":["Farklı düşünceler karşılaştırılarak bir sonuca ulaşılmıştır.","Güncel bir sorun sohbet havasında yorumlanmıştır.","Bir konu açıklayıcı bir anlatımla ele alınmıştır.","Bir düşünce örneklerle çürütülmeye çalışılmıştır."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t6-052","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Türk resim sanatında yeni bir dönemin öncüsü olan ve “Çallı Kuşağı” olarak da adlandırılan 1914 kuşağının özgün ressamlarından Avni Lifij’in otoportrelerinden, manzara resimlerinden ayrıca bir eleştirmen-yazar ve fotoğraf sanatçısı olarak yaptığı çalışmalardan oluşan 800’ü aşkın eseri Sakıp Sabancı Müzesi’nde sergilenmektedir.","stem":"Bu cümleden “Avni Lifij” ile ilgili aşağıdaki yargılardan hangisine kesinlikle ulaşılır?","options":["Farklı sanat dallarında eserleri bulunmaktadır.","Çallı Kuşağı’nın en ünlü temsilcisidir.","Eserlerinin tamamı Sakıp Sabancı Müzesi’nde sergilenmektedir.","1914 kuşağının öncüsüdür."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t6-053","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"I. Satın aldığımız gıda ürünlerinden yabancı madde çıkarsa hemen şikâyette bulunmalıyız. II. Öğrenci değişim programıyla ülkemize yabancı öğrenciler geldi. III. Yabancı araçlar sitemizin otoparkına bundan sonra giremeyecek.","stem":"Aşağıdakilerden hangisi “yabancı” sözcüğünün numaralanmış cümlelerde kazandığı anlamlardan biri değildir?","options":["Başka bir milletten olan","Belli bir yere veya kimseye özgü olmayan","Bir konuda bilgisi, deneyimi olmayan","Aynı türden, aynı çeşitten olmayan"],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t6-055","grade":8,"topic":"Anlatım biçimleri","difficulty":"Zor","outcome":"Anlatım biçimleri","text":"Bir dikiş iğnesiyle atılan minicik düğümler birbirine eklenerek işleyenin elinde gözleri kamaştıran motiflere dönüşür, kelimeleri aşan manalara ulaşır. Her motif vardığı diyarlarda, ulaştığı ellerde sese, kelimeye ihtiyaç duymaksızın farklı şeyleri konuşur. Anadolu’da işlenen “çayır çimen” adlı oyanın motifleri “Aramız, çayır çimen huzurunda olsun.” niyetini dile getirir mesela. İğne oyaları, bir mühendisin ince hesaplamalar neticesinde çizdiği büyük projelere eş değer kıymettedir. İşlevsellik bakımından iğne oyalarındaki her bir düğümün, harika yapılar oluşturmak için konmuş bir tuğladan farkı yoktur. Bu metnin anlatımında","stem":"Aşağıdaki düşünceyi geliştirme yollarından hangisi yoktur?","options":["Karşılaştırma","Tanımlama","Benzetme","Örnekleme"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t7-009","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"1953 yılında İstanbul’da dünyaya gelen Eşref Armağan, görme yetisi olmadığı ve hiçbir sanat eğitimi almadığı hâlde boyut ve perspektifi (eşya ve nesnelerin uzaktan görünüşü) kullanarak resim çizebiliyor. Sanatçı, çocukluğundan beri vazgeçemediği bu sanat dalında kendisini öyle geliştirmiş ki nesneleri âdeta dokunarak görüyor. Bu özelliğinden dolayı beyin yapısı Harvard Üniversitesinde incelenmiştir. Resimleri Amerika, Çin, İtalya gibi birçok ülkede sergilenen ünlü ressam belgesellere de konu olmuştur. Dünyanın en ünlü bestecisi ve piyanisti olarak kabul edilen Beethoven, Almanya’nın Bonn şehrinde fakir bir ailenin çocuğu olarak dünyaya geldi. Para kazanmak için küçük yaşta piyano çalmaya başladı. 1792 yılında Viyana’ya giden ve burada klasik müziğin ünlü ismi Joseph Haydn ile çalışma imkânı bulan Beethoven, Haydn’ın da yardımıyla müziğe olan yeteneğini keşfetti. 1801 yılında duyma kaybı yaşamaya başlayan ünlü besteci, duyma yetisini yıllar içinde kaybetse de müzik sevgisini hiç kaybetmedi. Hatta en ünlü eserlerinden biri olan 9. Senfoni’yi bestelerken duyma yetisini tamamen kaybetmişti.","stem":"Aşağıdakilerden hangisi bu metinlerde anlatılan sanatçıların ortak özelliklerinden biri değildir?","options":["Engelleri aşarak büyük başarılara imza atmış olmaları","Uluslararası bir üne sahip olmaları","Bilimsel araştırmalara konu edilmeleri","Yaptıkları işe tutkuyla bağlı olmaları"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t7-016","grade":8,"topic":"Yardımcı düşünce","difficulty":"Zor","outcome":"Yardımcı düşünce","text":"2021 YUNUS EMRE VE TÜRKÇE YILI Türk şiirinin kurucularından ve millî birliğin önemli tutkallarından biri olarak gösterilen Yunus Emre, halkı Hakk'a davet eden bir ahlak ve sevgi eğiticisidir. Yunus Emre, Anadolu’nun her karışını gezen ve yolu Hacı Bektaş Veli'nin dergâhına da uğrayan bir Hak erenidir. Onun Anadolu’da bir misyonu (görev) vardır. Bunu şu dörtlükte anlatmıştır: - - - unus Y Evrendeki tüm yaratılmışlar değerlidir. Emre Yunus Emre, tavır ve tutumlarına yön veren bu gerçeği şöyle ifade etmiştir: - - - - Yunus'un düşmanı nefrettir. Kimseyle 2021 yılı; UNESCO tarafından çatışmamaya, kavga etmemeye kararlıdır. tüm dünyada, her dönemin şairi Mücadele edilecek bir şey varsa o da heves olarak yaşatılmakta olan ve peşinde koşan nefistir yani insanın kendisidir. şiirlerinde kullandığı duru Türkçe","stem":"Bu durumu şu dizelerde ortaya koymuştur: - - - ile dilimizin gelişimine büyük katkı sağlayan sevgi ve irfan insanı \"Yunus Emre\"nin yılı ilan edildi. 15. Bu parçadan Yunus Emre ile ilgili aşağıdakilerden hangisi çıkarılamaz?","options":["Ulusal bütünlüğün sağlanmasında birleştirici bir rol üstlenmiştir.","Allah aşkını ve doğru davranış kurallarını insanlara öğretmiştir.","Kişiliği ve şiirleri, yaşadığı çağın dışında da ilgi uyandırmıştır.","Şiirleriyle toplumsal dil bilincinin oluşmasını sağlamıştır."],"answer":"C","solution":"Doğru cevap C seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t7-017","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Polisiye romanların bir numaralı ismi olan yazar, tüm eserlerinde okurlarını benzer bir sırrın peşinde koşturuyor ve her seferinde yanıltmayı başarıyor.","stem":"Bu cümlede sözü edilen yazarla ilgili, I. Okurları, her eserinde beklenmedik bir durumla karşılaşır. II. Polisiye roman alanında başarılıdır. III. Yapıtlarının hepsinde bir gizem vardır. yargılarından hangileri çıkarılabilir?","options":["Yalnız I","I ve II","II ve III","I, II ve III"],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t7-020","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Akıllı telefonlar, her geçen gün gelişerek hayatımızı kolaylaştırsa da bazı sağlık sorunlarını beraberinde getiriyor. Bu sorunların en önemli sebebi ise akıllı telefonların yaydığı radyasyon. Her telefonun yaydığı radyasyon değeri (SAR değeri) birbirinden farklı olmakla birlikte cep telefonu ile geçirilen süre, telefon görüşmelerinde kulaklık kullanılması ve telefonun sinyal gücünün seviyesi gibi değişkenler de radyasyona maruz kalma düzeyini etkiliyor. Bu","stem":"Metne göre, I. SAR değeri düşük telefonlar tercih edilmelidir. II. Telefon kullanılırken boyun ve bel duruşuna dikkat edilmelidir. III. Telefon, kullanılmadığı zamanlarda vücuttan uzak tutulmalıdır. önerilerinden hangileri sözü edilen tehlikeye yönelik bir çözüm olabilir?","options":["Yalnız I","I ve III","II ve III","I, II ve III"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t7-025","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Bitkiler oldum olası dikkatimi çekmiştir. Nerede daha önce görmediğim bir bitkiye rastlasam hemen adını, özelliklerini, türünü araştırma ihtiyacı hissederim. Bu araştırmalarım esnasında öğrendiğim kimi bitki isimleri beni hayli neşelendirir. Hayret, bu bitkiye neden böyle bir ad verilmiş, diye sorarım kendime. Örneğin küçük, mavi bir çiçek “unutmabeni” adıyla anılır. Bu güzelliği görüp de unutmak mümkün mü? Dokunulduğunda yapraklarını kapattığı için olsa gerek bir başkasının namı “küstüm otu”dur. Peki, Akdeniz’de yetişen ve köklerinden kırmızı boya elde edilen “havacıva”ya ne demeli? Kartopu, civanperçemi, ebegümeci, tekesakalı, devetabanı… Saymakla bitmez. İlginç isim ve bitkiler demişken aklıma geldi, güzel Türkçemizde birbirine ters duran iki çiçekten oluşan nakış motifine nedendir bilinmez (!) “eltieltiyeküstü” adı verilmiştir. Bu metnin anlatımıyla ilgili","stem":"Aşağıdakilerden hangisi söylenemez?","options":["Olasılık bildiren ifade vardır.","Mizahi bir dil kullanılmıştır.","Farklı duyularla ilgili ayrıntılara yer verilmiştir.","Tanık göstermeden yararlanılmıştır."],"answer":"D","solution":"Doğru cevap D seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t7-035","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Kış mevsiminin kırk gün süren en soğuk günlerine “zemheri” denir. Peki, “zemheri” sözcüğünün kökenini biliyor musunuz? “Zem” Farsçada “kış”, “herir” ise Arapçada “uğuldayan” anlamına gelmektedir. Dondurucu soğukların çatılarda uğuldamasından dolayı kışın en soğuk günlerine bu isim verilmiştir. Günümüzde zemheri yerine daha çok “kara kış” sözü kullanılmaktadır. Zemheri, kalıplaşmış birçok söze de konu olmuştur. Kışın ince giysi ile gezen kimseleri iğnelemek için “zemheri zürefası” sözü kullanılır. Bu sözdeki “zürefa” kelimesinin, uzun boyunlu bir hayvan olan “zürafa” ile herhangi bir anlam bağlantısı yoktur. “Zürefa” Arapça bir kelime olan ve “kibar, nazik” anlamına gelen “zarif” kelimesinin çoğuludur. Yine Arapça bir sözcük olan “zürafa” ise “hızlı yürüyen” anlamına gelmektedir.","stem":"Bu metinle ilgili aşağıdakilerden hangisi söylenemez?","options":["Olasılık bildiren cümle kullanılmıştır.","Bir durum, gerekçesiyle verilmiştir.","Bir kavramın tanımı yapılmıştır.","Örneklendirmeden yararlanılmıştır."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t8-028","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Ben akşam oturur, sabaha kadar satırları hislerime tercüman ederek şiir yazardım. Sabahleyin ise şiiri okur ama beğenmezdim. Onu yırtar, sabahtan akşama kadar yeni bir şiir kaleme alırdım. Çünkü insan, istediği şiiri ilk denemede I elde edemez; gönlünden geçen dizeleri kâğıda dökmekte zorlanır. Yazdıklarını defalarca silip tekrar yazar. Dizelerin, II III kalbinin aynası olduğuna kanaat getirdiğinde ise “Şimdi taşlar yerine oturdu ve yazdıklarım şiir oldu.” der. IV","stem":"Bu metinde numaralanmış sözlerden hangileri anlamca birbirine en yakındır?","options":["I ve II","I ve III","II ve IV","III ve IV"],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t8-029","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"(I) Avusturya’nın incisi Salzburg; etkileyici yapıları, yemyeşil doğası, görkemli dağları ve kulakların pasını silen klasik müziği ile ziyaretçilerine her daim masalsı bir atmosfer sunuyor. (II) Kışın burada dağ yürüyüşlerine çıkabilir, ellerinizle geyik besleyebilir ya da şehir merkezinde buz pateni yapabilirsiniz. (III) Klasik müzik sevdalısıysanız Mozart’ın doğduğu bu kentte festivallere katılabilir ya da bir restoranda akşam yemeğinizi canlı müzik eşliğinde yiyebilirsiniz. (IV) Salzburg’a kadar gelmişken, yeryüzü cennetlerinden biri olan Hallstatt’ı ziyaret ederek kendinizi harikalar diyarında hissedebilirsiniz.","stem":"Bu parçada numaralanmış cümlelerle ilgili aşağıdakilerden hangisi yanlıştır?","options":["I. cümlede betimleme yapılmıştır.","II. cümle amaç-sonuç cümlesidir.","III. cümlede koşul anlamı vardır.","IV. cümlede benzetme yapılmıştır."],"answer":"B","solution":"Doğru cevap B seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true},{"id":"g8-meb-sozel-t8-032","grade":8,"topic":"Paragrafta anlam","difficulty":"Zor","outcome":"Paragrafta anlam","text":"Bienal, Fransızca “yılaşırı” anlamına gelen ve iki yılda bir düzenlenen etkinliklere verilen addır. Çoğunlukla kültürel veya sanatsal faaliyetler için kullanılan bir terimdir. En eski bienal 1895’ten beri İtalya’da düzenlenen Venedik Bienali’dir. Türkiye’de de 1987 yılından beri düzenlenen Uluslararası İstanbul Bienali bulunmaktadır. Bienal etkinliklerini yöneten kişiye küratör denir. Küratör, bienalde sergilenecek eserlerin seçiminden gösterim alanlarının belirlenmesine kadar pek çok sorumluluğu üstlenir. Her bienalin kendine özgü bir teması vardır ve sergilenecek eserler bu tema üzerine kurgulanır.Tema belirlendikten sonra katılım sağlamaları için sanatçılara duyuru yapılır. Duyuruda bienalin teması ve tarihi açık bir şekilde belirtilir. Bu","stem":"Metne göre “bienal” etkinlikleriyle ilgili aşağıdakilerden hangisi söylenebilir?","options":["Belli bir konu çerçevesinde düzenlenir.","Kültürel ve sanatsal faaliyetlerle sınırlıdır.","İlk örneği Fransa’da görülmüştür.","Temasını belirleyen kişi küratördür."],"answer":"A","solution":"Doğru cevap A seçeneğidir.","wrong":"Metindeki kanıtları seçeneklerle yeniden karşılaştırınız.","strategy":"Soru kökünü okuyup metindeki ilgili kanıtları seçeneklerle karşılaştırınız.","hint":"Soru kökündeki sınırlayıcı ifadeye dikkat ediniz.","keepOptionOrder":true,"plainText":true}];
